  /* =====================================================================================
     reference.js: the desk's knowledge base. Glossary, methods, hard questions, model risk,
     data dictionary, episode atlas, reading list, checklists, playbooks, signals, changelog.
     Everything here is static content; live numbers come from data/*.json at runtime.
     ===================================================================================== */

  // id becomes the anchor g-<id>; at is the element id where the idea is used on the site
  const GLOSSARY = [
    { id: "hedge-algorithm", term: "Hedge (exponential weights)", alt: ["learner", "multiplicative weights"], def: "An online learner that holds a mix of policies and shifts weight toward those that did better, at a rate fixed in advance; its shortfall against the best single policy in hindsight is bounded.", at: "pf-pol-title" },
    { id: "regime-bootstrap", term: "Regime-switching bootstrap", alt: ["simulation"], def: "Simulated futures that switch between regimes as the fitted model does and draw each month's returns from real historical months in the same regime.", at: "pf-sim-title" },
    { id: "risk-parity", term: "Risk parity", alt: [], def: "Weights proportional to the inverse of each asset's volatility, so each contributes a similar share of risk when correlations are low.", at: "pf-pol-title" },
    { id: "evidence-gate", term: "Evidence gate", alt: ["gate"], def: "How far the decision engine moves the book from 1x toward its own optimum: none until its walked-forward utility gain over holding beats what the best of the strategies tried would show by luck.", at: "dx-title" },
    { id: "hmm", term: "Hidden Markov model", alt: ["regime model", "HMM"], def: "A model in which returns come from a few unseen regimes, each with its own mean and volatility, that persist and switch with fixed odds.", at: "dx-inf-title" },
    { id: "bocpd", term: "Bayesian online changepoint detection", alt: ["changepoint", "BOCPD"], def: "After each month, the probability distribution over how long the current regime has lasted; a mass near zero says something just changed.", at: "dx-inf-title" },
    { id: "deep-ensemble", term: "Deep ensemble", alt: ["neural-network ensemble"], def: "Several neural networks trained from different starting points; their disagreement measures what the model does not know.", at: "dx-mod-title" },
    { id: "model-averaging", term: "Dynamic model averaging", alt: ["model averaging"], def: "Weighting models by how well they predicted recent outcomes, with older scores slowly forgotten.", at: "dx-mod-title" },
    { id: "evpi", term: "Value of perfect information", alt: ["EVPI"], def: "How much better the decision would be if an unknown, such as the regime, were known for certain; the most any research on it can be worth.", at: "dx-dec-title" },
    { id: "bond-ladder", term: "Bond ladder", def: "Bonds with maturities spread evenly across a range; how the Bonds desk models each Treasury ETF.", at: "bd-set-title" },
    { id: "yield-breakeven", term: "Break-even yield rise", def: "How far yields can rise in a year before the year's income is gone: about the yield divided by the duration.", at: "bd-set-title" },
    { id: "strips-zero", term: "STRIPS", def: "Treasury coupons and principal sold separately as zero-coupon bonds; the longest-duration way to hold Treasuries (EDV, ZROZ).", at: "bd-set-title" },
    { id: "effective-sample", term: "Effective sample size", def: "How many independent observations a dataset really holds; overlapping 12-month returns hold about one a year.", at: "cmx-title" },
    { id: "stambaugh", term: "Stambaugh bias", def: "The small-sample bias that makes a persistent predictor such as a valuation ratio look more predictive than it is.", at: "cmx-title" },
    { id: "analog-month", term: "Analog month", def: "A past month most like a given one on valuation, rates, inflation, trend, volatility and drawdown, at least three years away.", at: "md-title" },
    { id: "event-study", term: "Event study", def: "The average return after a signal or event against all days, with errors that respect overlap; how every chart signal on the Analysis desk is judged.", at: "an-ta-title" },
    { id: "piotroski-f", term: "Piotroski F-score", def: "Nine pass-fail tests of profitability, leverage, liquidity and efficiency from two years of filings.", at: "an-fa-title" },
    { id: "beneish-m", term: "Beneish M-score", def: "Eight ratios that flag a higher chance of earnings manipulation; above -1.78 flags.", at: "an-fa-title" },
    { id: "reinforcement-learning", term: "Reinforcement learning", def: "Learning a policy that maximizes reward over time from experience; here, how much stock to hold each month.", at: "rl-title" },
    { id: "distribution-moat", term: "Distribution moat", def: "Owning the path to the customer, so new features reach users on day one.", at: "ed-dist-title" },
    { id: "data-hub", term: "Data hub", def: "One interface to every data source, tried in priority order per ticker with the source recorded.", at: "an-data-title" },
    { id: "affine-invariant", term: "Affine-invariant distance", def: "A distance between two covariance matrices that does not change when the assets are rescaled or mixed, so it compares the shape of risk rather than its size in any one unit.", at: "geo-map-title" },
    { id: "marchenko-pastur", term: "Marchenko-Pastur edge", def: "The largest eigenvalue a correlation matrix of pure noise would show for its number of series and months; eigenvalues above it are real common factors.", at: "geo-spec-title" },
    { id: "persistent-homology", term: "Persistent homology", def: "A record of how points join into clusters and form loops as a distance threshold grows; features that last across many thresholds are structure, the rest noise.", at: "geo-tda-title" },
    { id: "placebo-analogs", term: "Placebo test (analogs)", def: "The same forecast built from past windows chosen at random instead of the most similar ones; if it scores as well, the similarity is not what helps.", at: "geo-an-title" },
    { id: "ml-lab", term: "Machine-learning lab", def: "Seven forecasting models and two ensembles scored on whether they could have forecast next year's return using only what was known at the time; the flexible ones lose to the historical average out of sample, and only the simplest, a restricted combination, edges it, not significantly.", at: "ml-title" },
    { id: "purged-cv", term: "Purged cross-validation", def: "Cross-validation that drops training observations whose outcome window overlaps the test period, so overlapping labels cannot leak the answer.", at: "ml-cv-title" },
    { id: "taleb-fragility", term: "Fragility (Taleb-Douady)", def: "Losses that accelerate as the shock grows: the average of the outcomes at s - d and s + d is worse than the outcome at s.", at: "rt-f-title" },
    { id: "breakpoint", term: "Breakpoint", def: "The value of an assumption at which a model's conclusion flips.", at: "rt-bp-title" },
    { id: "kappa", term: "Kappa (Taleb)", def: "A 0 to 1 measure of fat tails based on how fast averages settle; it converts into how many observations a fat-tailed series needs to match a normal one.", at: "rt-t-title" },
    { id: "minbtl", term: "Minimum backtest length", def: "The years of data needed before a Sharpe ratio means anything, given how many variants were tried (Bailey and Lopez de Prado).", at: "rt-triage-title" },
    { id: "implied-erp", term: "Implied equity risk premium", def: "The discount rate that equates the index with the present value of its expected cash returns, minus the risk-free rate (Damodaran).", at: "ed-erp-title" },
    { id: "sales-to-capital", term: "Sales to capital", def: "Revenue per dollar of invested capital; in Damodaran's DCF it sets how much a company must reinvest to grow.", at: "ed-dcf-title" },
    { id: "belief-network", term: "Belief network", def: "The mind's thirteen linked claims; each starts from its own evidence and mean-field propagation lets connected claims pull on one another. Fixing one gives a what-if.", at: "md-net-title" },
    { id: "mind", term: "The mind", def: "The brain and the engine joined in one graph of about 2,600 nodes (concepts, markets, checked facts, quotes, engine modules, ML models, tested assumptions, sources, economies, companies, signals) with a reasoning loop that recalls, spreads activation, weighs evidence and proposes an action it never executes.", at: "md-title" },
    { id: "spreading-activation", term: "Spreading activation", alt: ["personalized PageRank"], def: "Relevance that flows from the nodes a question names along weighted links, step by step, with some always returning to the start. The mind runs 40 steps with continue probability 0.75.", at: "md-how-title" },
    { id: "bm25", term: "BM25", def: "The ranking formula search engines use: a word counts more when it is rare across all documents and frequent in this one, with diminishing returns and a length correction.", at: "md-how-title" },
    { id: "log-odds", term: "Log-odds", def: "The logarithm of p/(1 − p). Independent pieces of evidence add in log-odds; the total converts back to a probability with 1/(1 + e^(−x)).", at: "md-how-title" },
    { id: "hinge", term: "Hinge", def: "The single signal whose removal would move the mind's verdict the most; shown with the verdict without it.", at: "md-how-title" },
    { id: "working-bias", term: "Averaging bias (Working 1960)", def: "Monthly averages of prices make returns look smoother and more trending than they were; a rule tested on averaged data must act a month late to be honest.", at: "lb-tr-title" },
    { id: "markov-switching", term: "Markov switching", alt: ["Hamilton model"], def: "A model in which the data switch between hidden regimes, such as calm and turbulent, with fixed odds of staying (Hamilton 1989).", at: "lb-rg-title" },
    { id: "garch", term: "GARCH(1,1)", def: "Volatility that clusters: today's variance is a base level plus a share of yesterday's squared shock plus a share of yesterday's variance (Bollerslev 1986).", at: "lb-rg-title" },
    { id: "convenience-yield", term: "Convenience yield", def: "The benefit of holding a commodity now rather than later; high when inventories are short, which puts futures below spot (backwardation).", at: "cr-c-t" },
    { id: "pot-odds", term: "Pot odds", def: "The share of the final pot a call costs: call ÷ (pot + call). Call when your chance of winning is higher.", at: "cr-eq-t" },
    { id: "batna", term: "BATNA", def: "Best alternative to a negotiated agreement (Fisher and Ury 1981): what you do if this deal fails, which sets your walk-away price.", at: "cr-b-t" },
    { id: "j-curve", term: "J-curve", def: "A private fund's cumulative cash flow to its investors dips in the early years, as capital is called and fees paid, before distributions lift it.", at: "cr-y-t" },
    { id: "subagent", term: "Subagent", def: "A separate instance of Claude given one narrow job and a brief, working in parallel and returning one report, which the lead agent treats as data to check.", at: "ag-title" },
    { id: "bp", term: "Basis point", alt: ["bp"], def: "One hundredth of a percentage point: 0.01%. Yields and spreads move in basis points.", at: "rates-title" },
    { id: "par-yield", term: "Par yield", def: "The coupon at which a bond prices at exactly 100. The Treasury's daily curve is a par curve.", at: "rates-title" },
    { id: "yield-curve", term: "Yield curve", alt: ["curve"], def: "Yields across maturities on one date. Upward sloping is normal; inverted, with short yields above long, has preceded recessions.", at: "rates-title" },
    { id: "duration", term: "Duration", alt: ["modified duration"], def: "Percent price change for a one-point move in yield, sign flipped. A duration of 15 means about −15% for a 1% rise in yield.", why: "The single most important number in a bond hedge.", at: "bc-title" },
    { id: "macaulay", term: "Macaulay duration", def: "The present-value-weighted average time to a bond's cash flows. Modified duration is Macaulay divided by (1 + y/2).", at: "bc-title" },
    { id: "convexity", term: "Convexity", def: "How duration changes as yields move. Positive convexity means a bond gains more when yields fall than it loses when they rise by the same amount.", why: "Long bonds and long options are convex; that asymmetry is what a hedge buys.", at: "bc-title" },
    { id: "dv01", term: "DV01", alt: ["dollar value of a basis point"], def: "The dollar gain or loss on a position when yields move one basis point.", why: "Hedges are matched in DV01, not in notional.", at: "ct-title" },
    { id: "steepener", term: "Steepener", alt: ["flattener", "bull steepener", "bear flattener"], def: "A curve trade that profits when the long-minus-short spread widens; a flattener profits when it narrows. Bull and bear say whether yields are falling or rising.", at: "ct-title" },
    { id: "2s10s", term: "2s10s", def: "The 10-year Treasury yield minus the 2-year, in basis points. The most-watched measure of curve slope.", at: "spread-tiles" },
    { id: "real-yield", term: "Real yield", def: "Yield after inflation, read from TIPS.", why: "In 2026, real yields did the tightening.", at: "decomp" },
    { id: "breakeven", term: "Breakeven inflation", alt: ["breakeven", "breakevens"], def: "The nominal Treasury yield minus the TIPS real yield at the same maturity: the inflation rate at which the two pay the same.", at: "decomp" },
    { id: "tips", term: "TIPS", def: "Treasury Inflation-Protected Securities: principal indexed to CPI, so they pay a real yield.", at: "sec-tips" },
    { id: "term-premium", term: "Term premium", def: "Extra yield investors demand to hold a long bond instead of rolling short bills. Estimated by models: Kim-Wright on FRED, ACM at the New York Fed.", why: "A rising term premium is how stocks and bonds fall together.", at: "rates-title" },
    { id: "forward-rate", term: "Forward rate", alt: ["forward", "forwards", "5y5y"], def: "The rate for a future period locked in today, implied by the curve. The 5y5y is the 5-year rate starting 5 years from now.", at: "fw-title" },
    { id: "zero-rate", term: "Zero rate", alt: ["spot rate", "zero curve"], def: "The yield on a single cash flow at one date, bootstrapped from par yields. The building block for forwards.", at: "fw-title" },
    { id: "carry", term: "Carry", def: "What a position earns if prices do not move. For a financed bond: its coupon minus the financing rate.", at: "fw-title" },
    { id: "roll-down", term: "Roll-down", def: "The price gain as a bond ages into a lower-yielding part of an upward-sloping curve.", at: "fw-title" },
    { id: "breakeven-move", term: "Breakeven yield move", def: "How far yields can rise over the holding period before carry and roll-down are used up.", at: "fw-title" },
    { id: "cmt", term: "Constant maturity yield", def: "The Treasury's interpolated yield at a fixed maturity (DGS10 is the 10-year). The engine rebuilds bond returns from these.", at: "dict-title" },
    { id: "bill", term: "Treasury bill", alt: ["T-bills", "bills"], def: "Treasury debt maturing within a year, sold at a discount. The safe leg of a barbell.", at: "sec-treasury-bills" },
    { id: "ctd", term: "Cheapest to deliver", alt: ["CTD"], def: "The bond a futures seller will deliver because it costs least after the conversion factor. Futures track its price and DV01.", at: "fut-title" },
    { id: "conversion-factor", term: "Conversion factor", def: "CME's multiplier that puts every deliverable bond on a common footing: the bond's price at a 6% yield.", at: "fut-title" },
    { id: "treasury-futures", term: "Treasury futures", def: "Exchange-traded contracts on notes and bonds (ZN, TN, ZB, UB). They add or remove duration for margin instead of cash.", at: "fut-title" },
    { id: "basis-trade", term: "Basis trade", def: "Long cash Treasuries, short futures, financed in repo and run at high leverage. Its unwinds can make Treasuries fall in a crisis, as in March 2020.", at: "ep-covid-2020" },
    { id: "repo", term: "Repo", def: "A collateralized short-term loan against securities; the financing rate for levered bond positions.", at: "fw-title" },
    { id: "sofr", term: "SOFR", def: "The Secured Overnight Financing Rate: what it costs to borrow cash overnight against Treasuries.", at: "liq-title" },
    { id: "iorb", term: "IORB", alt: ["interest on reserve balances"], def: "The rate the Fed pays banks on their reserves. Repo trading above it means cash is scarce.", at: "liq-title" },
    { id: "reserves", term: "Bank reserves", alt: ["reserves"], def: "Banks' deposits at the Fed, the system's settlement cash. When they get scarce, repo rates jump, as in September 2019.", at: "liq-title" },
    { id: "tga", term: "Treasury General Account", alt: ["TGA"], def: "The Treasury's cash account at the Fed. When it rises on tax receipts or new debt, bank reserves fall, all else equal.", at: "liq-title" },
    { id: "rrp", term: "Overnight reverse repo", alt: ["reverse repo", "ON RRP"], def: "A Fed facility where money funds park cash overnight. It held more than $2 trillion in 2022 and is now nearly empty, so drains come out of bank reserves.", at: "liq-title" },
    { id: "net-liquidity", term: "Net liquidity", def: "Fed assets minus the Treasury General Account minus overnight reverse repo: a rough measure of the cash the Fed leaves in the private system.", at: "liq-title" },
    { id: "qt", term: "Quantitative tightening", alt: ["QT"], def: "The Fed shrinking its balance sheet by letting bonds mature without reinvesting. It ended on Dec 1, 2025.", at: "liq-title" },
    { id: "credit-spread", term: "Credit spread", alt: ["spreads"], def: "Extra yield over Treasuries that pays for default and liquidity risk.", at: "rates-live-sec" },
    { id: "oas", term: "OAS", alt: ["option-adjusted spread"], def: "Option-adjusted spread: the credit spread after stripping out embedded options. The ICE BofA indices on FRED report it.", at: "rates-live-sec" },
    { id: "high-yield", term: "High yield", alt: ["junk"], def: "Bonds rated below BBB−.", at: "sec-high-yield-bonds" },
    { id: "ccc", term: "CCC spread", def: "The option-adjusted spread on the lowest-rated junk bonds, CCC and below: where credit stress shows first.", at: "signals" },
    { id: "investment-grade", term: "Investment grade", def: "Bonds rated BBB− or better.", at: "sec-investment-grade-corporates" },
    { id: "cds", term: "Credit default swap", alt: ["CDS"], def: "Insurance on a borrower's default, paid as an annual spread.", at: "sec-credit-default-swaps" },
    { id: "private-credit", term: "Private credit", def: "Loans made by funds and insurers instead of banks, held to maturity and marked by models.", at: "pc-title" },
    { id: "clo", term: "CLO", alt: ["collateralized loan obligation"], def: "A pool of leveraged loans cut into tranches from AAA to equity.", at: "sec-clos" },
    { id: "bdc", term: "BDC", alt: ["business development company"], def: "A listed vehicle that holds private loans. Its discount to book value is a real-time read on private credit marks.", at: "t6" },
    { id: "beta", term: "Beta", def: "A return's sensitivity to a factor. A market beta of 1.2 means about 1.2% for each 1% the market moves.", at: "fut-title" },
    { id: "factor", term: "Factor", def: "A common driver of returns. The engine uses three: market (QQQ), AI (the basket minus QQQ) and rates (TLT).", at: "eng-title" },
    { id: "fcf", term: "Free cash flow", def: "Operating cash flow minus capital expenditure.", at: "capex-live-sec" },
    { id: "capex", term: "Capex", alt: ["capital expenditure"], def: "Spending on long-lived assets: data centers, chips, power.", at: "capex-live-sec" },
    { id: "depreciation", term: "Depreciation", def: "Capex expensed over an asset's useful life. Stretching assumed server lives lowers reported expense, which is Burry's point.", at: "lens-michael-burry" },
    { id: "hyperscaler", term: "Hyperscaler", alt: ["hyperscalers"], def: "A company running cloud data centers at the largest scale: Amazon, Microsoft, Alphabet, Meta, Oracle.", at: "t1" },
    { id: "call-put", term: "Call and put", alt: ["call", "put", "puts", "calls"], def: "A call is the right to buy at the strike; a put is the right to sell.", at: "bs-title" },
    { id: "strike", term: "Strike", def: "The price at which an option can be exercised.", at: "bs-title" },
    { id: "implied-vol", term: "Implied volatility", alt: ["implied vol"], def: "The volatility that makes Black-Scholes match an option's market price: the market's price of future movement.", at: "bs-title" },
    { id: "realized-vol", term: "Realized volatility", def: "How much a price actually moved, annualized. Implied minus realized is the volatility risk premium that option sellers earn.", at: "iv-title" },
    { id: "vrp", term: "Volatility risk premium", alt: ["volatility premium"], def: "Implied minus realized volatility: what buyers of protection pay sellers, on average, for carrying crash risk. Usually positive; negative in a crash, when realized outruns implied.", why: "The price of insurance relative to the risk it covers.", at: "iv-title" },
    { id: "vix-term", term: "VIX term structure", alt: ["contango", "backwardation"], def: "VIX against longer-dated implied volatility such as the 3-month VIX. Normally upward sloping (contango); inverted (backwardation) when fear is concentrated in the next month.", at: "iv-title" },
    { id: "vxn", term: "VXN", def: "Cboe's Nasdaq-100 volatility index: the VIX for the index this book tracks.", at: "iv-title" },
    { id: "black-scholes", term: "Black-Scholes", def: "The 1973 option-pricing model, here with a dividend yield. It assumes one constant volatility, which skew contradicts.", at: "bs-title" },
    { id: "delta", term: "Delta", def: "Option price change per $1 move in the underlying.", at: "bs-title" },
    { id: "gamma", term: "Gamma", def: "How fast delta changes as the underlying moves. Long options are long gamma: they gain from large moves either way.", at: "bs-title" },
    { id: "vega", term: "Vega", def: "Option price change per one-point change in implied volatility.", at: "bs-title" },
    { id: "theta", term: "Theta", def: "Option value lost per day as expiry approaches, all else equal: the rent on convexity.", at: "bs-title" },
    { id: "skew", term: "Skew", def: "Out-of-the-money puts trade at higher implied volatility than at-the-money options, because crashes are what investors pay to insure.", at: "tb-title" },
    { id: "put-spread", term: "Put spread", alt: ["put spreads"], def: "Long a put, short a lower-strike put: cheaper insurance with a capped payout.", at: "po-title" },
    { id: "collar", term: "Collar", alt: ["collars"], def: "A long put paid for by selling a call: protection funded with upside.", at: "po-title" },
    { id: "covered-call", term: "Covered call", def: "Long the stock, short a call: income that gives away upside and keeps the downside.", at: "po-title" },
    { id: "vix", term: "VIX", def: "The S&P 500's 30-day implied volatility, from listed options. Above 30 is stress; below 15 is calm, when protection is cheap.", at: "sig-title" },
    { id: "tail-hedge", term: "Tail hedge", def: "Protection that pays only in large drawdowns, run as a standing yearly budget.", at: "tb-title" },
    { id: "barbell", term: "Barbell", def: "Taleb's shape: most capital very safe, a small part in very convex bets, little in the fragile middle.", at: "po-title" },
    { id: "spot-vol-grid", term: "Spot-vol grid", def: "Position P&L across moves in the underlying and in implied volatility: how an options desk reads its risk.", at: "grid-title" },
    { id: "correlation", term: "Correlation", def: "How closely two return series move together, from −1 to +1.", at: "regime-title" },
    { id: "stock-bond", term: "Stock-bond correlation", def: "The correlation of stock and bond returns. Negative means bonds hedge stocks. It was negative from about 2000 until 2021 and has been near zero or positive since.", why: "The variable the whole desk is built around.", at: "regime-title" },
    { id: "ewma", term: "EWMA", alt: ["exponentially weighted"], def: "Exponentially weighted moving average: recent days count more. With a 63-day half-life a day's weight halves every 63 trading days.", at: "eng-title" },
    { id: "hysteresis", term: "Hysteresis", def: "A switch that needs a bigger move to change state than to stay in it, so the regime label does not flicker around zero.", at: "eng-title" },
    { id: "regime", term: "Regime", def: "The engine's state for the stock-bond relationship: hedging, neutral or amplifying.", at: "live" },
    { id: "min-var", term: "Minimum-variance hedge ratio", alt: ["min-variance"], def: "The hedge size that minimizes the variance of book plus hedge: minus their covariance over the hedge's variance.", at: "hedge" },
    { id: "rho-squared", term: "ρ² rule", def: "A hedge can remove at most the squared correlation of a book's variance: 9% at a −0.3 correlation, 49% at −0.7.", at: "lanes-title" },
    { id: "var", term: "Value at risk", alt: ["VaR"], def: "The loss not exceeded on a given share of days. A 99% one-day VaR is the 1-in-100-days loss.", at: "live" },
    { id: "es", term: "Expected shortfall", def: "The average loss on days worse than VaR: what the tail actually costs.", at: "live" },
    { id: "fhs", term: "Filtered historical simulation", def: "Historical returns rescaled by today's volatility forecast, so VaR responds to current conditions.", at: "live" },
    { id: "drawdown", term: "Drawdown", def: "The fall from a portfolio's peak to its trough.", at: "size" },
    { id: "vol-target", term: "Volatility targeting", alt: ["vol targeting", "vol target"], def: "Scaling exposure so forecast volatility hits a target: less exposure when markets are wild.", at: "size" },
    { id: "kelly", term: "Kelly criterion", alt: ["Kelly"], def: "The bet size that maximizes long-run growth: expected excess return over variance. Fractional Kelly bets less because the edge is uncertain.", at: "size" },
    { id: "gross-net", term: "Gross exposure", alt: ["gross"], def: "Longs plus shorts as a share of capital. Net is longs minus shorts.", at: "size" },
    { id: "beta-adjusted", term: "Beta-adjusted exposure", def: "Exposure scaled by beta: what the book's dollars are worth in index terms.", at: "fut-title" },
    { id: "stress-test", term: "Stress test", def: "Revaluing the book under a historical or hypothetical shock.", at: "hedge" },
    { id: "ergodicity", term: "Ergodicity", def: "Whether a strategy's average across many people equals its average over time for one person. With ruin possible it does not, which is why the desk sizes for survival.", at: "lens-nassim-taleb" },
    { id: "fat-tails", term: "Fat tails", def: "Extreme moves far more often than a normal distribution predicts.", at: "lens-nassim-taleb" },
    { id: "sharpe", term: "Sharpe ratio", alt: ["Sharpe"], def: "Excess return per unit of volatility, annualized.", at: "live" },
    { id: "deflated-sharpe", term: "Deflated Sharpe ratio", alt: ["deflated Sharpe"], def: "The probability that a Sharpe ratio is real after charging for the number of strategies tried and for skew and fat tails (Bailey and López de Prado).", at: "live" },
    { id: "look-ahead", term: "Look-ahead bias", alt: ["look-ahead"], def: "Using information in a backtest that was not available at the time.", why: "The engine's canary test fails the build if timing ever leaks.", at: "eng-title" },
    { id: "walk-forward", term: "Walk-forward test", alt: ["walk-forward"], def: "Fit on the past, test on the next period, roll forward. Purging removes overlap so a test never sees its own training data.", at: "eng-title" },
    { id: "brier", term: "Brier score", def: "Mean squared error of probability forecasts. The skill score compares it with always forecasting the base rate.", at: "eng-title" },
    { id: "auc", term: "AUC", def: "The probability a model ranks a random positive case above a random negative one; 0.5 is a coin flip.", at: "eng-title" },
    { id: "overfitting", term: "Backtest overfitting", def: "Picking the best of many trials and mistaking luck for skill.", at: "eng-title" },
    { id: "float", term: "Float", def: "Premiums an insurer holds before paying claims: money it invests but does not own.", at: "how-title" },
    { id: "solvency-ii", term: "Solvency II ratio", def: "A European insurer's available capital over required capital; above 100% meets the rule.", at: "cos-title" },
    { id: "all-weather", term: "All Weather", def: "Bridgewater's risk-balanced portfolio, built to hold up across growth and inflation surprises.", at: "regime-title" },
    { id: "reflexivity", term: "Reflexivity", def: "Soros's idea that prices feed back into the fundamentals they reflect.", at: "lens-george-soros" },
    { id: "prediction-market", term: "Prediction market", alt: ["prediction markets"], def: "Contracts that pay $1 if an event happens; the price reads as a probability.", at: "sec-prediction-markets" },
    { id: "carry-trade", term: "Carry trade", def: "Borrowing in a low-yielding currency, often the yen, to buy higher-yielding assets. It earns slowly and unwinds fast, as in August 2024.", at: "ep-carry-2024" },
    { id: "z-score", term: "Z-score", alt: ["standard deviations"], def: "How many standard deviations a move sits from the average. Under a normal distribution a 2σ week comes about once in 22; fat tails make it more common.", at: "mv-title" },
    { id: "fwd-inflation", term: "5y5y inflation expectation", def: "The breakeven inflation rate for the five years starting five years from now. The Fed reads it as long-run inflation credibility.", at: "levels-title" },
    { id: "velocity", term: "Velocity", alt: ["rate of change", "rates of change"], def: "How fast a series moves: the least-squares slope of its last 13 weeks of prints, per week (three months for monthly data).", at: "roc-title" },
    { id: "acceleration", term: "Acceleration", alt: ["second derivative"], def: "Whether the move is speeding up: today's 13-week velocity minus the velocity 13 weeks ago.", at: "roc-title" },
    { id: "time-to-trigger", term: "Time to trigger", def: "Distance to a rule's line divided by the velocity, when the market is moving toward it: when the rule fires if the pace holds.", at: "roc-title" },
    { id: "hedge-line", term: "Inflation hedge line", alt: ["hedge line"], def: "Since 1871, with three-year inflation above about 2.75 to 4.25%, stocks and bonds have mostly moved together. Chosen on data through 2016 only and tested on the decade after, the line is 4.25%; a bootstrap puts it anywhere from 2.75% to 4.25%.", at: "fi-title" },
    { id: "evidence-label", term: "Evidence label", alt: ["observed", "estimated", "assumed", "hypothesis"], def: "Every number carries one: Observed (a published print), Estimated (a model fit to data), Assumed (an input someone chose), Historical pattern, Hypothesis (a claim to test), or Unavailable.", at: "today7" },
    { id: "posterior", term: "Posterior", alt: ["bayes", "bayesian update"], def: "The probability of each scenario after the evidence: prior times the likelihood of what was observed, normalized. Signals that share a driver are averaged so one cause counts once.", at: "solve-title" },
    { id: "evsi", term: "Value of information", alt: ["EVSI", "EVPI"], def: "How much better the decision gets, on average, from learning a signal before acting, in basis points of certainty-equivalent return. Perfect foresight (EVPI) is the ceiling.", at: "rzv-title" },
    { id: "reverse-stress", term: "Reverse stress test", def: "The most plausible joint move of the risk factors that produces a given loss: the point on the loss boundary closest to today in Mahalanobis distance.", at: "rzr-title" },
    { id: "nash", term: "Nash equilibrium", alt: ["equilibrium", "best response"], def: "A set of choices where no player gains by changing theirs alone. It need not be good for anyone: the capex race and the crowded exit are both equilibria.", at: "games-title" },
    { id: "cournot", term: "Cournot competition", def: "Firms choose quantities; the price falls with the total. Each firm ignores the price cut it imposes on the others, so the industry overbuilds: 2N/(N+1) times the joint-profit quantity.", at: "gtc-title" },
    { id: "global-game", term: "Global game", alt: ["Morris-Shin"], def: "A coordination game with noisy private information. It turns a bank run's multiple equilibria into one threshold: below it, everyone runs.", at: "gtx-title" },
    { id: "kyle-lambda", term: "Kyle's lambda", def: "Price impact per unit of net order flow when a market maker cannot tell informed from uninformed traders: σ<sub>v</sub>/(2σ<sub>u</sub>).", at: "gtk-title" },
    { id: "markout", term: "Markout", def: "Signed price move after a fill, measured from the fill price to the midpoint some time later: the edge at the fill plus the move after it.", at: "fq-title" },
    { id: "frechet", term: "Fréchet bounds", def: "The range a joint probability can take without assuming independence: from max(0, Σp − (n − 1)) to min p.", at: "as-title" },
    { id: "eff-bets", term: "Effective independent bets", alt: ["effective bets", "effective risk contributors"], def: "Two different counts. Effective risk contributors = 1/Σ(risk share²) by position; effective independent bets = exp(entropy) of risk across principal components. Two perfectly correlated positions score 2 and 1.", at: "pol-title" },
    { id: "base-effect", term: "Base effect", alt: ["base effects"], def: "A change in an average or a yearly rate caused by which months drop out of the window, not by what happens now.", at: "dec-title" },
    { id: "minsky", term: "Minsky stages", alt: ["hedge finance", "speculative finance", "Ponzi finance"], def: "Hyman Minsky's three borrowing postures: cash flow covers everything (hedge), covers interest only (speculative), or neither (Ponzi).", at: "mi-title" },
    { id: "nonop", term: "Non-operating income", alt: ["paper profits"], def: "Income outside the business: gains on investments, interest and the like. For the builders, mostly marks on stakes in other AI companies.", at: "pp-title" },
    { id: "rpo", term: "Remaining performance obligations", alt: ["RPO"], def: "Revenue already contracted but not yet recognized: the reported backlog.", at: "bl-title" },
    { id: "useful-life", term: "Useful life", alt: ["server life", "server lives"], def: "The years over which an asset is depreciated. A longer life lowers each year's depreciation and raises reported earnings.", at: "dw-title" },
    { id: "conjunction", term: "Conjunction", def: "All of several things being true at once. Its probability is the product of theirs when they are independent.", at: "as-title" },
    { id: "fragility", term: "Fragility", def: "The desk's ranking of an assumption: (1 − probability) × impact. High fragility is likely to fail and costly when it does.", at: "as-title" },
    { id: "known-unknowns", term: "Known unknowns", alt: ["unknown unknowns", "known knowns", "unknown knowns"], def: "The four quadrants of what we know and know we know, each with its own response: act, size the range, audit, or prepare.", at: "kk-title" },
    { id: "second-order", term: "Second-order thinking", alt: ["second order", "fourth order"], def: "Following a shock past its first effect to what that effect forces others to do, and what that forces in turn.", at: "ch-title" },
    { id: "calibration", term: "Calibration", def: "Whether the things you call 70% likely happen 70% of the time. Scored with the Brier score and a calibration chart.", at: "jrs-title" },
    { id: "alpha", term: "Alpha", def: "Return after the market's share: return minus beta times the benchmark's return.", at: "jrs-title" },
    { id: "aar", term: "After-action review", def: "The US Army's debrief: what was supposed to happen, what did, why, and what to sustain or improve.", at: "jr-title" },
    { id: "pre-mortem", term: "Pre-mortem", def: "Imagining a decision has already failed and writing down why, before making it.", at: "jr-title" },
    { id: "black-swan", term: "Black swan", alt: ["black swans", "gray swan", "gray swans"], def: "Taleb's term for a rare, extreme event that is explained only after the fact. A gray swan is one that can be named in advance.", at: "atlas-title" },
    { id: "tail-index", term: "Tail index", alt: ["Hill estimator"], def: "How fast extreme losses thin out. Moments of order α and above do not exist; stock returns sit near 2 to 4 depending on how much of the tail is used; this site measures about 2.2 (research) and 3.8 (labs) on monthly S&P 500 returns.", at: "tails-title" },
    { id: "cape", term: "CAPE", alt: ["cyclically adjusted P/E"], def: "Shiller's price over ten years of average real earnings. High readings have preceded low ten-year returns.", at: "fi-title" },
    { id: "capacity-price", term: "Capacity price", alt: ["capacity auction"], def: "What a grid operator pays generators to be available in a future year. PJM's has cleared at its cap twice.", at: "gr-title" },
    { id: "megaproject", term: "Megaproject", alt: ["megaprojects"], def: "A project costing a billion dollars or more. Flyvbjerg's data: 8.5% finish on time and on budget.", at: "mp-title" },
    { id: "lindy", term: "Lindy effect", def: "For ideas and institutions, every year survived adds to the expected remaining life.", at: "tal-title" },
    { id: "volatility-drag", term: "Volatility drag", def: "Compound growth falls short of the average return by about half the variance.", at: "lab-title" },
    { id: "likelihood-ratio", term: "Likelihood ratio", def: "How much more often a signal fires when the event is coming than when it is not: the factor by which it moves the odds.", at: "lab-title" },
    { id: "desk-read", term: "Desk read", def: "The one-line summary above the signals board: how many signals are red or amber, and which playbook they argue for.", at: "signals" },
    { id: "avellaneda-stoikov", term: "Avellaneda-Stoikov", def: "A market maker's optimal quotes: shade the mid by inventory times risk aversion times variance, and quote a spread that pays for both inventory risk and the depth of the book.", at: "mmas-title" },
    { id: "adverse-selection", term: "Adverse selection", def: "Losing to counterparties who know more. A market maker's spread must cover what informed traders take (Glosten and Milgrom).", at: "gm-title" },
    { id: "square-root-law", term: "Square-root impact", alt: ["square-root law"], def: "Market impact grows with the square root of order size relative to daily volume: four times the size, twice the impact per share.", at: "ex-title" },
    { id: "almgren-chriss", term: "Almgren-Chriss", def: "The optimal schedule for working a large order: trade faster to cut timing risk, slower to cut impact; the urgency parameter sets the balance.", at: "ex-title" },
    { id: "internalization", term: "Internalization", alt: ["off-exchange"], def: "Filling orders against a dealer's own book instead of on an exchange. About half of US share volume now trades off exchange.", at: "mms-title" },
    { id: "zero-dte", term: "0DTE", alt: ["same-day options"], def: "Options that expire the day they trade. Two thirds of S&P 500 option volume in July 2026.", at: "mms-title" },
    { id: "expectancy", term: "Expectancy", def: "Average profit per trade in units of risk (R): win rate times average win, minus loss rate times average loss, minus costs.", at: "pe-title" },
    { id: "funded-challenge", term: "Funded-account challenge", alt: ["prop challenge"], def: "A paid evaluation: hit a profit target before breaching a daily or total loss limit to trade the firm's capital.", at: "chal-title" },
    { id: "pass-through", term: "Pass-through fees", def: "Costs a multi-manager fund charges investors on top of fees: PM pay, data, technology. 3 to 10% of NAV a year.", at: "pr-pods-title" },
    { id: "leontief", term: "Leontief inverse", def: "The total effect of a shock through every chain of links in a network, (I − W)⁻¹: the sum of first, second, third and higher-order effects.", at: "brw-title" },
    { id: "spectral-radius", term: "Spectral radius", def: "The largest eigenvalue size of a network's link matrix. Below 1, shocks fade as they travel; at or above 1, some loop feeds on itself.", at: "brw-title" },
    { id: "feedback-loop", term: "Feedback loop", alt: ["reinforcing loop", "balancing loop"], def: "A chain of links that returns to where it started. A positive product of the links reinforces a shock; a negative one damps it.", at: "brw-title" },
    { id: "dated-brent", term: "Dated Brent", def: "The price of physical North Sea cargoes loading soon. It traded about $27 over Brent futures in October 2026: the physical market is tighter than the futures say.", at: "nwc-title" },
    { id: "pik", term: "PIK", alt: ["payment in kind"], def: "Interest paid with more debt instead of cash. Rising PIK, above all amended after the loan was made, is a disguised default.", at: "bs-credit-title" },
    { id: "reverse-dcf", term: "Reverse DCF", def: "Solving for the growth a price already assumes, instead of the price a forecast implies.", at: "bsc-title" },
    { id: "cash-eps", term: "Cash EPS", def: "Earnings per share after setting depreciation to economic life, counting stock pay as pay, expensing capitalized software and crediting deferred revenue.", at: "bsc-title" },
    { id: "moonbag", term: "Moonbag", def: "What is left of a winner after selling enough to recover the original cost: a free position on the right tail.", at: "bsz-title" },
    { id: "student-t", term: "Student-t", def: "A bell-shaped distribution with fat tails. Fitted to 156 years of monthly stocks, it has about 3.8 degrees of freedom.", at: "bst-title" },
    { id: "ooda", term: "OODA loop", def: "Observe, orient, decide, act: Boyd's decision cycle. The Decision loop desk runs it end to end and says when to loop again.", at: "oo-title" },
    { id: "reverse-dcf-implied", term: "Implied growth", alt: ["expectations investing"], def: "The ten-year revenue growth a discounted cash flow needs to justify today's price. Rappaport and Mauboussin's way to read what a price expects instead of guessing what it should be.", at: "ps-title" },
    { id: "base-rate", term: "Base rate", alt: ["outside view"], def: "How often something has happened in a large reference class. For growth: the share of companies of the same size that ever grew that fast for a decade.", at: "ps-title" },
    { id: "owner-earnings", term: "Steady-state free cash flow", alt: ["owner earnings"], def: "Operating cash flow less maintenance capex (taken as D&A) less stock pay: what the business would throw off if it stopped growing.", at: "ps-title" },
    { id: "accruals", term: "Accruals", def: "Earnings not yet backed by cash: net income minus operating cash flow, scaled by assets. High accruals have historically preceded weaker earnings (Sloan, 1996).", at: "ps-title" },
    { id: "granger", term: "Granger causality", def: "One series' past improving the forecast of another beyond its own past. Predictive precedence, not proof of cause.", at: "brl-title" },
    { id: "graphical-lasso", term: "Graphical lasso", def: "Estimating which pairs of series are linked once all the others are held fixed, with a penalty that sets most links to exactly zero; the penalty is chosen by the extended BIC.", at: "atv-title" },
    { id: "stability-selection", term: "Stability selection", def: "Refitting on many half-samples of the data and keeping only what is selected in most of them; it comes with a bound on the expected number of false links.", at: "atv-title" },
    { id: "var-lingam", term: "VAR-LiNGAM", def: "A structural vector autoregression whose same-month causal order is learned from the non-Gaussian shape of the shocks instead of assumed.", at: "atv-title" },
    { id: "connectedness", term: "Connectedness index", def: "Diebold and Yilmaz: the share of each series' forecast-error variance caused by shocks to the other series, averaged; it rises when markets move as one.", at: "atv-roll-title" },
    { id: "modularity", term: "Modularity", def: "How much more densely a network's communities are linked inside than chance would give; communities here are found by Newman's leading eigenvector.", at: "atv-sys-title" },
    { id: "conformal", term: "Conformal interval", def: "An error bar whose width comes from the model's own past errors rather than an assumed distribution; the adaptive version adjusts its target after every miss, so long-run coverage holds even when the world shifts.", at: "brr-title" },
    { id: "stacking", term: "Stacking", def: "Combining rival models with the weights that maximize their out-of-sample predictive score: the data votes on which world model to trust, month by month.", at: "brr-title" },
    { id: "robustness-value", term: "Robustness value", def: "The share of the residual variance of both cause and effect that an unseen common cause would have to explain to erase an estimated link (Cinelli and Hazlett, 2020).", at: "brr-title" },
    { id: "neumann", term: "Neumann series", def: "The sum x₀ + W′x₀ + W′²x₀ + …: a shock's effect order by order. It converges to (I − W′)⁻¹x₀ when the spectral radius of W is below 1.", at: "hero-title" },
    { id: "kill-criteria", term: "Kill criterion", def: "The evidence, written down before acting, that would prove a decision wrong and trigger its reversal.", at: "oo-act-title" },
    { id: "dro", term: "Distributionally robust choice", alt: ["robust to the odds"], def: "Choosing the portfolio whose worst expected outcome is best across every set of scenario odds within a stated distance of your own. It protects against being wrong about the probabilities, not just about the outcome.", at: "rzd-title" },
    { id: "huber", term: "Huber regression", alt: ["robust regression"], def: "A regression in which unusually large errors count linearly instead of quadratically, so a handful of extreme months cannot carry the estimate.", at: "brl-title" },
    { id: "newey-west", term: "Newey-West", alt: ["HAC"], def: "Standard errors that allow neighbouring months to be correlated and volatility to change. Usually wider, and more honest, than the textbook ones.", at: "brl-title" },
    { id: "pbo", term: "Probability of backtest overfitting", alt: ["PBO"], def: "How often the rule that looked best in one half of history lands in the bottom half of the other. Near 50% means the backtest winner was mostly luck.", at: "book-body" },
    { id: "block-bootstrap", term: "Block bootstrap", def: "Re-running history many times by stitching together random blocks of real days, keeping calm and stormy stretches intact, to see how much a result depends on the exact path.", at: "book-body" },
    { id: "model-comparison", term: "Bayesian model comparison", alt: ["which world"], def: "Ranking versions of a model by how probable each makes the data actually seen. The brain uses it to ask whether today's readings look more like the 1990 to 2021 world or the 2022-on world.", at: "brf-title" },
    { id: "counterfactual", term: "Counterfactual", def: "What would have happened had one thing been different, keeping everything the evidence says about everything else. Pearl's third rung, above seeing and doing.", at: "brf-title" },
    { id: "shapley", term: "Shapley value", alt: ["but-for"], def: "A fair split of a total among its causes. In a linear model each cause's share is its own effect, and the shares add up exactly to the whole.", at: "brf-title" },
    { id: "lingam", term: "DirectLiNGAM", alt: ["causal discovery"], def: "A method that learns which variable causes which from data alone, using the fact that real shocks are not bell-shaped. It assumes linear links and no hidden common cause.", at: "brl-title" },
    { id: "kalman", term: "Kalman filter", alt: ["Kalman smoother"], def: "A way to track a quantity that drifts over time from noisy data, month by month, with an honest band around it. The brain uses it to watch each measured link move.", at: "brl-title" },
    { id: "mahalanobis", term: "Mahalanobis distance", alt: ["surprise"], def: "How far a set of readings sits from what a model expects, allowing for how the readings move together. Large means the model is missing something.", at: "brf-title" },
    { id: "abduction", term: "Abduction", alt: ["inference to the best explanation"], def: "Reasoning from effects back to causes: which root shocks, taken together, best explain every reading at once. The brain solves it exactly as a ridge regression of the readings on the root causes.", at: "brt-title" },
    { id: "mutual-information", term: "Mutual information", alt: ["information gain"], def: "How much learning one thing is expected to reduce doubt about another, in bits or nats. The brain and the Field desk use it to pick what to look at next.", at: "brt-title" },
    { id: "do-intervention", term: "Doing vs seeing", alt: ["intervention"], def: "Setting a value cuts its causes, so only what lies downstream moves; seeing the same value also tells you something about its causes. The gap is what the observation signals.", at: "brt-title" },
    { id: "three-clocks", term: "Three clocks", def: "When something happened (economic), when a series or filing shows it (publication), and when prices reflect it (market). Field observations record the first two.", at: "fdc-title" },
    { id: "hearsay", term: "Hearsay", def: "A claim relayed by someone who did not see it. On the Field desk it can raise a question but never settle one.", at: "fdn-title" },
    { id: "heat-score", term: "Heat score", alt: ["niche skew"], def: "How unusual today's mentions of a theme are against its last 28 days; niche skew is how much of the talk comes from sources few people read.", at: "nws-title" },
  ];

  // formulas render as HTML: <var> for symbols, <sub>/<sup>, .frac for fractions
  const METHODS = [
    { group: "The shape of the market (v0.22)", items: [
      { name: "Covariance as a point on a curved space", f: "C<sub>t</sub> = (&Sigma;x x<sup>T</sup> &minus; (&Sigma;x)(&Sigma;x)<sup>T</sup>/w)/(w &minus; 1) from cumulative sums; log C = U log(&Lambda;) U<sup>T</sup>", say: "Every 36-month window at once; the matrix logarithm flattens the space so distances and averages apply.", where: "geometry.py rolling_cov, log_euclid" },
      { name: "Affine-invariant distance", f: "d(A, B) = &#8214; log(A<sup>&minus;1/2</sup> B A<sup>&minus;1/2</sup>) &#8214;<sub>F</sub> = (&Sigma; log<sup>2</sup> &lambda;<sub>i</sub>)<sup>1/2</sup>", say: "Unchanged if the assets are rescaled or mixed: it compares the shape of risk. One batched eigenvalue call against every past window.", where: "geometry.py affine_invariant" },
      { name: "The era map", f: "D<sup>2</sup><sub>ij</sub> = G<sub>ii</sub> + G<sub>jj</sub> &minus; 2G<sub>ij</sub>, G = L L<sup>T</sup>; B = &minus;&frac12; J D<sup>2</sup> J, coordinates = top eigenvectors of B scaled by &radic;&lambda;", say: "Every distance from one Gram matrix, then classical multidimensional scaling.", where: "geometry.py covariance_study, classical_mds" },
      { name: "Analogs and their placebo", f: "p(r<sub>t+1</sub>) = &frac18; &Sigma;<sub>j</sub> N(m&#772; + &lambda;(m<sub>j</sub> &minus; m&#772;), &frac12;s<sub>j</sub><sup>2</sup> + &frac12;s&#772;<sup>2</sup>), &lambda; = 12/48", say: "The 8 nearest windows ending before today's began, 36 months apart; scored against the same model built from 8 random and 8 farthest windows.", where: "decide.py geo_walk; geometry.py engine_model_study" },
      { name: "The noise edge", f: "&lambda;<sub>&plusmn;</sub> = (1 &plusmn; &radic;q)<sup>2</sup>, q = N/T; absorption ratio = &Sigma;<sub>i&le;N/5</sub> &lambda;<sub>i</sub> / N", say: "Eigenvalues above &lambda;<sub>+</sub> are factors; jumps in the ratio tested with a block permutation.", where: "geometry.py spectrum_study, mp_edges" },
      { name: "Persistent homology", f: "d<sub>ij</sub> = &radic;(2(1 &minus; &rho;<sub>ij</sub>)); H0 deaths = minimum spanning tree; H1 = pivots of the edge-triangle boundary matrix over Z/2", say: "Bitset column reduction in filtration order.", where: "geometry.py mst_h0, rips_h1, topology_study" },
      { name: "Transport and paths", f: "SW<sub>1</sub> = mean<sub>&theta;</sub> mean |sort(X&theta;) &minus; sort(Y&theta;)|; A = &frac12; &Sigma; (x<sub>k</sub> &Delta;y<sub>k</sub> &minus; y<sub>k</sub> &Delta;x<sub>k</sub>)", say: "Whole distributions compared by sorting; the Levy area says which series moved first.", where: "geometry.py sliced_w, transport_study, levy_area" },
      { name: "Memory and drag", f: "F(n) ~ n<sup>H</sup> (DFA); E[log(1 + r)] &asymp; E[r] &minus; &sigma;<sup>2</sup>/2", say: "Hurst by era against shuffled data; the arithmetic-geometric gap against the drag, by decade.", where: "geometry.py dfa_hurst, compounding_study" },
    ] },
    { group: "The matrix shortcut (v0.21)", items: [
      { name: "The filter as a scan", f: "a<sub>t</sub> = a<sub>1</sub> C<sub>2</sub> C<sub>3</sub> ... C<sub>t</sub>, C<sub>t</sub> = A diag(b<sub>t</sub>); all prefixes by doubling: Q<sub>t</sub> &larr; Q<sub>t&minus;d</sub> Q<sub>t</sub>, d = 1, 2, 4, ...", say: "log2(T) rounds of batched matrix products instead of T steps; each partial product rescaled to a total of 1 with its log carried.", where: "infer.py _scan, forward_backward" },
      { name: "Smoothed odds from scans", f: "&gamma;<sub>t</sub> &prop; &alpha;&#770;<sub>t</sub> &#8728; &beta;&#770;<sub>t</sub>; &xi;<sub>t</sub>(i, j) &prop; &alpha;&#770;<sub>t</sub>(i) A<sub>ij</sub> b<sub>t+1</sub>(j) &beta;&#770;<sub>t+1</sub>(j), each normalized", say: "The backward pass is the same scan over suffixes; nothing else changes in the EM.", where: "infer.py forward_backward" },
      { name: "Many questions as one matrix", f: "R &larr; (1 &minus; a) S + a P R, P[j, i] = w<sub>ij</sub> / deg<sub>i</sub>, columns of S the questions' seeds", say: "Every column is exactly the single walk; the work is shared.", where: "mind.py walk_matrix, spread_many, think_many, board; mind.js mindSpreadMany" },
      { name: "The 64-number map", f: "S = D<sup>&minus;1/2</sup> W D<sup>&minus;1/2</sup> &asymp; U &Lambda; U<sup>T</sup> (64 eigenpairs); (I &minus; aS)<sup>&minus;1</sup> &asymp; I + U diag(a&lambda; / (1 &minus; a&lambda;)) U<sup>T</sup>", say: "Fast and close, not exact: used to find related ideas, not to answer.", where: "mind.py spectral, spread_fast, related" },
      { name: "Every shock against every holding", f: "T = I + W + W<sup>2</sup> + ... + W<sup>K</sup>; column r of T is a unit shock at root r", say: "One sum of matrix powers answers all pairs at once.", where: "brain.js brTotal; mx.js" },
    ] },
    { group: "The portfolio engine (v0.20)", items: [
      { name: "Regimes of several assets", f: "x<sub>t</sub> | s<sub>t</sub> = k ~ N(μ<sub>k</sub>, Σ<sub>k</sub>), Σ<sub>k</sub> shrunk 5% toward its diagonal; Baum-Welch with warm starts, K by BIC", say: "Each regime carries its own correlations, including stocks with Treasuries.", where: "infer.py mvhmm_fit, mvhmm_filter, mvviterbi" },
      { name: "Utility over a grid of mixes", f: "max<sub>w</sub> Σ<sub>k</sub> p<sub>k</sub> Σ<sub>q</sub> ω<sub>q</sub> u(1 + w·(μ<sub>k</sub> + L<sub>k</sub> z<sub>q</sub>) − b (Σw − 1)<sup>+</sup>), 343 Gauss-Hermite nodes per state; s.t. ES<sub>5%</sub> ≤ 12%", say: "Exact integration of each state's normal, so the choice is not Monte Carlo noise.", where: "portfolio.py Chooser" },
      { name: "The learner (Hedge)", f: "w<sub>i,t</sub> ∝ exp(−η Σ<sub>s&lt;t</sub> ℓ<sub>i,s</sub>), ℓ = −log(1 + r), η = √(8 ln N / T) / L fixed in advance", say: "Regret against the best policy in hindsight is at most ln N / η + η T L² / 8.", where: "infer.py hedge_weights; portfolio.py meta_learner" },
      { name: "Gate over every policy", f: "the policy with the largest utility t over holding is the candidate; g = max(0, 2Φ(t − t<sub>0</sub>) − 1)", say: "The book moves toward a process only as far as its record, deflated for the tries, allows.", where: "portfolio.py build" },
      { name: "Regime-switching bootstrap", f: "s<sub>t+1</sub> ~ A[s<sub>t</sub>], s<sub>0</sub> ~ today's filtered odds; x<sub>t</sub> drawn from the historical months labelled s<sub>t</sub> by Viterbi", say: "Tails and co-movement from history, persistence from the chain.", where: "portfolio.py simulate" },
      { name: "The decision in the page", f: "the same mixture, quadrature nodes, borrowing rate, risk budget and gate as decide.what_if", say: "The tests check the page and Python agree to 1e-12 on every exposure's certainty equivalent.", where: "dxlive.js dxlDecide; decide.py what_if" },
    ] },
    { group: "The decision engine (v0.19)", items: [
      { name: "Hidden Markov regimes", f: "r<sub>t</sub> | s<sub>t</sub> = k ~ N(μ<sub>k</sub>, σ<sub>k</sub><sup>2</sup>), P(s<sub>t</sub> = j | s<sub>t−1</sub> = i) = A<sub>ij</sub>; Baum-Welch with scaling, K by BIC; filtered α<sub>t</sub> ∝ (α<sub>t−1</sub>A) ∘ b(r<sub>t</sub>)", say: "The regime odds at each month use only data up to that month; refit every five years.", where: "infer.py hmm_fit, hmm_filter, viterbi; decide.py regime_walk" },
      { name: "Shrunk regime means", f: "μ̃<sub>k</sub> = μ̄ + n<sub>k</sub>/(n<sub>k</sub> + 120) (μ<sub>k</sub> − μ̄), n<sub>k</sub> = π<sub>k</sub> T from the stationary distribution", say: "A rarely visited state is mostly prior, so it cannot size the book on a few months.", where: "decide.py shrink" },
      { name: "Bayesian online changepoints", f: "P(r<sub>t</sub> | data) over run lengths; growth ∝ P(r<sub>t−1</sub>) π(x<sub>t</sub>)(1 − H), reset ∝ Σ P π(x<sub>t</sub>) H, H = 1/120, Normal-Gamma prior, Student-t predictive", say: "How long the current regime has lasted, and the chance it began in the last six months.", where: "infer.py bocpd" },
      { name: "Dynamic model averaging", f: "w<sub>m,t</sub> ∝ exp(Σ<sub>s ≤ t−2</sub> 0.98<sup>t−2−s</sup> log p<sub>m</sub>(r<sub>s</sub>))", say: "Each return model's weight is its discounted out-of-sample log score.", where: "decide.py averaging_weights" },
      { name: "Stacked forecasts", f: "w = argmin<sub>w ≥ 0, Σw = 1</sub> Σ<sub>s</sub> (y<sub>s</sub> − Σ<sub>m</sub> w<sub>m</sub> f<sub>m,s</sub>)<sup>2</sup> over forecasts whose 12-month outcome had ended", say: "Weights only from forecasts already scored; never from the month being forecast.", where: "infer.py stack; decide.py forecast_walk" },
      { name: "Deep ensemble", f: "five networks (8 → 16 → 8 → 1, GELU, dropout 0.1, weight decay, Adam, early stopping on the newest fifth); σ<sup>2</sup> = mean dropout variance + variance of member means + training residual variance", say: "Gradients are checked against finite differences to 1e-7; uncertainty grows away from the data.", where: "nn.py MLP, DeepEnsemble, gradcheck" },
      { name: "Utility-optimal exposure", f: "x* = argmax<sub>x ∈ [0, 1.5]</sub> E[((1 + x R − b (x − 1)<sup>+</sup>)<sup>1−γ</sup> − 1)/(1 − γ)] s.t. x ES<sub>5%</sub>(R) ≤ 12%, R a normal mixture, Gauss-Hermite quadrature", say: "γ is set once, on 1871 to 1939, so that holding is optimal on average.", where: "decide.py utility, choose, calibrate_gamma" },
      { name: "Evidence gate", f: "g = max(0, 2Φ(t − t<sub>0</sub>) − 1), t the Newey-West t of the engine's monthly utility gain over holding, t<sub>0</sub> = Φ<sup>−1</sup>(1 − 1/N) for N strategies tried; x = 1 + g (x* − 1)", say: "The engine moves the book only as far as its own walked-forward record earns.", where: "decide.py utility_gain, gate_from_t, gated" },
      { name: "Value of knowing the regime", f: "EVPI = Σ<sub>k</sub> w<sub>k</sub> max<sub>x</sub> U<sub>k</sub>(x) − max<sub>x</sub> Σ<sub>k</sub> w<sub>k</sub> U<sub>k</sub>(x), in certainty-equivalent return", say: "What perfect regime knowledge would add; an upper bound on what regime research can be worth.", where: "decide.py today" },
      { name: "Kalman stock-bond beta", f: "r<sub>t</sub> = a<sub>t</sub> + b<sub>t</sub> Δy<sub>t</sub> + e<sub>t</sub>, (a, b) a random walk; filtered estimates and standard errors", say: "The stock market's response to the 10-year yield, as it was known at each month.", where: "infer.py kalman_regression" },
      { name: "Conservative RL", f: "B fitted-Q agents on stationary-bootstrap resamples; act on argmax<sub>a</sub> (mean Q − κ sd Q), κ = 1", say: "Where the agents disagree, pessimism: the action falls back toward caution.", where: "decide.py rl_conservative" },
      { name: "Hedge selector", f: "per context (regime stressed or calm × trend on or off) and hedge, a discounted normal posterior of log growth; choose the highest posterior mean; Thompson draws give P(best)", say: "Full feedback, so an experts problem rather than a bandit.", where: "decide.py hedge_selector" },
    ] },
    { group: "The engine's framework (v0.18)", items: [
      { name: "Content-addressed cache", f: "key = SHA-256(name, source of the modules it depends on, canonical encoding of the arguments)", say: "Same code and same data, same key: a result is computed once. Entries carry a checksum; a corrupted one is dropped and recomputed.", where: "core/cache.py memo, fetch" },
      { name: "Dependency graph", f: "B waits for A when B reads a file A writes; Kahn's algorithm orders the engines and refuses a cycle", say: "Independent engines run at the same time, each in its own process.", where: "core/runner.py graph, levels" },
      { name: "Last-good fallback", f: "outputs copied aside before a run; restored if the engine fails, times out or writes a file that breaks its contract", say: "A bad day shows yesterday's numbers, marked, not a broken page.", where: "core/runner.py, core/contracts.py" },
      { name: "Personalized PageRank, vectorized", f: "r ← (1 − α) s + α (Aᵀ r) with A<sub>ij</sub> = w<sub>ij</sub> / deg<sub>i</sub>, 40 steps", say: "The mind's spreading activation as sparse arithmetic; the page's typed-array version agrees to 1e-12.", where: "mind.py spread, mind.js mindSpread" },
    ] },
    { group: "Bonds, complexity and history (v0.17)", items: [
      { name: "A bond's price", f: "P = Σ<sub>t</sub> (100 c/2) (1 + y/2)<sup>−2t</sup> + 100 (1 + y/2)<sup>−2T</sup>, coupon dates counted back from maturity every half year", say: "A price is promised payments discounted at a yield; nothing else goes in.", where: "bondlab.py bond_price, bondlab.js blPrice" },
      { name: "An ETF as a ladder", f: "maturities equally spaced across [a, b], centred on the reported average maturity; one coupon c solves D<sub>ladder</sub>(c) = D<sub>reported</sub> by bisection", say: "STRIPS funds (EDV, ZROZ) pay no coupon.", where: "bondlab.py setup, calibrate" },
      { name: "Moving the curve", f: "Δy(T) = Δ<sub>10</sub> + (Δ<sub>30</sub> − Δ<sub>10</sub>) min(1, (T − 10)/20) for T ≥ 10; Δ<sub>10</sub> below 10 years, or Δ<sub>10</sub> (T − 1)/9 with the front end anchored", say: "The 10-year and 30-year land exactly where they are set; today's hump is kept.", where: "bondlab.py shift_at" },
      { name: "Twelve-month return and break-even", f: "R = (V<sub>1y</sub>(y′(T − 1)) + cash paid) / V<sub>0</sub> − 1; break-even ≈ yield / duration", say: "The move happens now, yields then hold; each bond is repriced at the yield for its remaining maturity, so it earns the roll.", where: "bondlab.py fund_horizon, breakeven" },
      { name: "Stocks per point of yield", f: "r<sub>t</sub> = a + b Δy10<sub>t</sub> + e<sub>t</sub>, by inflation over the prior 36 months (below 2.75%, 2.75% to 4.25%, above 4.25%), Newey-West t with 6 lags", say: "Shiller's monthly data since 1871.", where: "bondlab.py equity_readthrough" },
      { name: "Effective sample and the cost of estimation", f: "n<sub>eff</sub> ≈ months / 12; expected out-of-sample loss of OLS ≈ p / n<sub>eff</sub>", say: "Overlapping 12-month returns repeat eleven months of information each month.", where: "complexity.py information" },
      { name: "Stambaugh bias", f: "E[b̂ − b] ≈ −(ρ σ<sub>u</sub>/σ<sub>v</sub>)(1 + 3φ)/T, checked by simulation under no predictability", say: "A persistent predictor whose shocks move with returns makes a useless slope look useful.", where: "complexity.py stambaugh" },
      { name: "Analog months", f: "distance = ‖z<sub>i</sub> − z<sub>j</sub>‖ over standardized log CAPE, 10-year yield, inflation, trend gap, volatility and drawdown; 8 nearest at least 36 months apart", say: "Each month in the chronicle links to the months most like it.", where: "chronicle.py analogs" },
    ] },
    { group: "Technicals, fundamentals, RL and data (v0.16)", items: [
      { name: "Wilder smoothing, ATR and ADX", f: "W<sub>t</sub> = W<sub>t−1</sub> + (x<sub>t</sub> − W<sub>t−1</sub>)/n; TR = max(H − L, |H − C<sub>−1</sub>|, |L − C<sub>−1</sub>|); ADX = W(100 |+DI − −DI| / (+DI + −DI))", say: "Seeded with the first n-bar mean.", where: "technicals.py" },
      { name: "Signal event study", f: "edge = mean(s<sub>t</sub> · r<sub>t+1</sub>), t by Newey-West; BH across signals; weight = t²/(t² + 4) if t &gt; 0", say: "A signal at t trades at t+1; the composite is Σ w s / N.", where: "technicals.py event_study, analyze" },
      { name: "Piotroski F", f: "nine tests: ROA &gt; 0, CFO &gt; 0, ΔROA &gt; 0, CFO &gt; NI, Δleverage ≤ 0, Δcurrent ratio &gt; 0, no new shares, Δgross margin &gt; 0, Δturnover &gt; 0", say: "A test whose inputs are not filed is unknown, not failed.", where: "statements.py piotroski" },
      { name: "Altman Z''", f: "6.56 WC/TA + 3.26 RE/TA + 6.72 EBIT/TA + 1.05 BE/TL", say: "Above 2.6 safe, below 1.1 distress.", where: "statements.py altman_z2" },
      { name: "Beneish M", f: "−4.84 + 0.92 DSRI + 0.528 GMI + 0.404 AQI + 0.892 SGI + 0.115 DEPI − 0.172 SGAI + 4.679 TATA − 0.327 LVGI", say: "Above −1.78 flags; missing inputs default to neutral and are listed.", where: "statements.py beneish" },
      { name: "Fitted Q iteration", f: "Q(s, p, a) ← [Σ<sub>t: s<sub>t</sub> = s</sub> (r(a, p, R<sub>t</sub>) + γ max<sub>a′</sub> Q(s<sub>t+1</sub>, a, a′)) + k Q̄] / (n<sub>s</sub> + k)", say: "Reward ln(1 + a R − cost |a − p| − borrow (a − 1)<sup>+</sup>) − λ min(0, ·)²; γ = 0.9; k pseudo-months of prior.", where: "rl.py fit" },
      { name: "Restricted combination forecast", f: "r̂ = max(0, (1/K) Σ<sub>k</sub> (r̄ + b<sub>k</sub>(x<sub>k</sub> − x̄<sub>k</sub>))), b<sub>k</sub> = 0 if its sign contradicts theory", say: "Rapach, Strauss and Zhou (2010) with Campbell and Thompson (2008).", where: "ml.py Combination" },
      { name: "Accuracy-weighted ensemble", f: "w<sub>k</sub> ∝ 1 / Σ<sub>s ≤ t−H−1</sub> δ<sup>t−1−s</sup> e<sub>ks</sub>², δ = 0.9<sup>1/12</sup>", say: "Stock and Watson's discounted MSPE; only outcomes already known count.", where: "ml.py dmspe" },
    ] },
    { group: "Machine learning, the reality check and the edge (v0.15)", items: [
      { name: "Purged walk-forward", f: "train on months t &lt; T − H − e, forecast T, refit every 12 months; H = 12, e = 1", say: "Each forecast uses only what was knowable; the purge drops the 12 months whose outcomes overlap the forecast's.", where: "ml.py walk_forward · ML lab" },
      { name: "Out-of-sample skill and Diebold-Mariano", f: "skill = 1 − Σe²<sub>model</sub>/Σe²<sub>mean</sub>, &nbsp; DM = d̄ / √(NW var(d)/n), d = e²<sub>mean</sub> − e²<sub>model</sub>", say: "Newey-West at 12 lags because 12-month outcomes overlap.", where: "ml.py score, diebold_mariano" },
      { name: "CPCV and PBO", f: "8 blocks, test on 2: C(8,2) = 28 splits; PBO = share of splits where the in-sample best ranks below the out-of-sample median", say: "López de Prado (2018); Bailey, Borwein, López de Prado and Zhu (2015).", where: "ml.py cpcv" },
      { name: "Split-conformal interval", f: "± q<sub>0.8</sub>(|e|) over the last 360 out-of-sample errors", say: "Coverage is measured, not assumed.", where: "ml.py conformal" },
      { name: "Analogs and novelty", f: "standardized Euclidean distance; novelty = mean distance to the 24 nearest months, ranked against every month's own", say: "No two analogs within 18 months.", where: "ml.py analogs, shift" },
      { name: "Taleb's kappa", f: "κ = 2 − (log n − log n<sub>0</sub>) / log(M(n)/M(n<sub>0</sub>)), &nbsp; n<sub>eq</sub> = 30<sup>(2−κ)/(2(1−κ))</sup>", say: "M is the mean absolute deviation of a sum of n draws, by resampling; n = 30, n<sub>0</sub> = 1.", where: "assumptions.py kappa" },
      { name: "Fragility heuristic", f: "H(s) = ½[f(−s−d) + f(−s+d)] − f(−s), &nbsp; d = 5%, s = 5% to 30%", say: "Taleb and Douady (2013): negative H means losses accelerate.", where: "assumptions.py fragility" },
      { name: "Hedge breakpoint", f: "σ(book + w·bond) &lt; σ(book) ⟺ ρ &lt; −w σ<sub>b</sub> / (2σ<sub>e</sub>)", say: "w = 30%, σ<sub>e</sub> = 18%, σ<sub>b</sub> = TLT's duration (16.5, the solver's calibration) × the annual volatility of the 10-year yield since 1871.", where: "assumptions.py hedge_breakpoint" },
      { name: "Triage of a backtest", f: "live = (SR − c·turns/σ)(1 − decay), &nbsp; DSR = Φ((SR<sub>p</sub> − E[max]) √(n−1) / √(1 − γ<sub>3</sub>SR<sub>p</sub> + (γ<sub>4</sub>−1)/4·SR<sub>p</sub>²)), &nbsp; MinBTL = (E[max z]/SR)²", say: "Decay 26% out of sample, 58% after publication (McLean and Pontiff 2016); E[max] of N skill-less tries scattered by 1/√years.", where: "assumptions.py triage · reality.js rtTriage" },
      { name: "Stressed worlds", f: "stationary block bootstrap, mean block 12 months, 600-month histories, 400 draws", say: "Again drawing only from inflationary months.", where: "assumptions.py worlds" },
      { name: "Implied ERP", f: "P = Σ<sub>t≤5</sub> CF<sub>t</sub>/(1+r)<sup>t</sup> + CF<sub>5</sub>(1+r<sub>f</sub>)/((r − r<sub>f</sub>)(1+r)<sup>5</sup>), &nbsp; ERP = r − r<sub>f</sub>", say: "Solved by bisection.", where: "damodaran.py implied_erp · edge.js dmErp" },
      { name: "Narrative DCF", f: "FCFF = EBIT(1 − t) − ΔRevenue/(sales to capital); TV = NOPAT<sub>11</sub>(1 − g/WACC)/(WACC − g), g ≤ r<sub>f</sub>; value = (1 − p)·V + p·½V", say: "Growth fades to the terminal rate over years 6 to 10; the cost of capital drifts to 8.5%.", where: "damodaran.py narrative_dcf · edge.js dmDcf" },
      { name: "Belief network", f: "L<sub>j</sub> = b<sub>j</sub> + γ Σ<sub>i</sub> w<sub>ij</sub> m<sub>i</sub>, &nbsp; m = 2p − 1, γ = 0.6, 60 damped steps; verdict row capped at 0.3", say: "w from the atlas's 12-month impulse responses between each claim's series; fixing a claim is a what-if.", where: "mind.py network, propagate · mind.js mindPropagate" },
    ] },
    { group: "The mind (v0.14)", items: [
      { name: "Recall", f: "score<sub>i</sub> = 0.6 · BM25<sub>i</sub>/max BM25 + alias<sub>i</sub>, &nbsp; BM25 = Σ<sub>w</sub> idf(w) · f(k<sub>1</sub>+1)/(f + k<sub>1</sub>(1 − b + b·L/L̄)), &nbsp; k<sub>1</sub> = 1.2, b = 0.75", say: "Each node's document is its name three times, other names twice and text once. An exact name in the question adds 0.6 to 1 by its length. Before normalizing, BM25 is damped by kind (quotes 0.55; signals, investors and economies 0.7 to 0.8; companies and industries 0.85). Up to 12 seeds scoring at least 30% of the best.", where: "mind.py Mind.recall · mind.js mindRecall" },
      { name: "Spreading activation", f: "r<sup>(t+1)</sup> = (1 − α)s + α P<sup>⊤</sup>r<sup>(t)</sup>, &nbsp; P<sub>ij</sub> = w<sub>ij</sub>/Σ<sub>k</sub>w<sub>ik</sub>, &nbsp; α = 0.75, 40 steps", say: "Personalized PageRank from the seeds over the undirected, typed, weighted graph. Within 2·0.75<sup>40</sup> of the exact fixed point.", where: "mind.py Mind.spread · mind.js mindSpread" },
      { name: "Weighing a claim", f: "L = Σ<sub>i</sub> sign<sub>i</sub> · s<sub>i</sub> · rel<sub>i</sub> · (0.5 + 0.5√(a<sub>i</sub>/a<sub>max</sub>)) · k<sub>i</sub><sup>−1/2</sup>, &nbsp; p = 1/(1 + e<sup>−L</sup>)", say: "s is strength, rel the reliability of that kind of evidence, a the signal's activation, k its rank within its family. The range leaves each family out in turn; the hinge is the largest |term|.", where: "mind.py Mind.weigh" },
      { name: "Causal chain to the book", f: "argmin<sub>path</sub> Σ −ln min(0.95, max(0.05, |w<sub>e</sub>|))", say: "Dijkstra over the atlas's learned and judged directed links; the sign of the chain is the product of the link signs.", where: "mind.py Mind.chains" },
    ] },
    { group: "Labs and the card room (v0.14)", items: [
      { name: "RSI (Wilder)", f: "RSI = 100 − 100/(1 + avg gain<sub>14</sub>/avg loss<sub>14</sub>), Wilder smoothing 1/14", say: "Above 70 is called overbought, below 30 oversold.", where: "labs.py rsi" },
      { name: "MACD and Bollinger", f: "MACD = EMA<sub>12</sub> − EMA<sub>26</sub>, signal = EMA<sub>9</sub>(MACD); bands = SMA<sub>20</sub> ± 2σ<sub>20</sub>", say: "EMA weight 2/(n+1) on the newest price.", where: "labs.py macd, bollinger" },
      { name: "Stationary bootstrap and max test", f: "blocks of geometric length (mean 12 months); p = share of resamples whose best centred variant beats the observed best", say: "Politis and Romano (1994); the max test follows White's reality check and Hansen's SPA in spirit.", where: "labs.py trend_lab" },
      { name: "Out-of-sample R²", f: "R²<sub>OS</sub> = 1 − Σ(r − r̂<sub>model</sub>)²/Σ(r − r̄<sub>expanding</sub>)²", say: "Campbell and Thompson (2008): above zero means the model beat the historical mean in real time.", where: "labs.py valuation_lab" },
      { name: "Holm and Benjamini-Hochberg", f: "Holm: p<sub>(k)</sub>·(m − k + 1), running max; BH: p<sub>(k)</sub>·m/k, running min from the top", say: "Holm controls any false positive; BH the share of false ones among those declared.", where: "labs.py holm, bh" },
      { name: "Theory of storage", f: "F = S·e<sup>(r + u − y)T</sup>, &nbsp; y = r + u − ln(F/S)/T, &nbsp; roll = ln(F<sub>near</sub>/F<sub>far</sub>)·12/months", say: "Kaldor (1939), Working (1949).", where: "games2.py carry_price, implied_convenience, roll_yield" },
      { name: "Bargaining", f: "Rubinstein: x<sub>1</sub> = (1 − δ<sub>2</sub>)/(1 − δ<sub>1</sub>δ<sub>2</sub>); best take-it-or-leave-it ask p* = (high + cost)/2", say: "The ask maximizes (p − cost)·P(accept) when the other side's walk-away is uniform between low and high.", where: "games2.py rubinstein, best_offer" },
      { name: "Private funds", f: "IRR: Σ CF<sub>t</sub>/(1+IRR)<sup>t</sup> = 0; PME = Σ D<sub>t</sub>·I<sub>T</sub>/I<sub>t</sub> + NAV over Σ C<sub>t</sub>·I<sub>T</sub>/I<sub>t</sub>; Yale: C<sub>t</sub> = RC<sub>t</sub>(commit − paid), D<sub>t</sub> = (t/L)<sup>B</sup>·NAV<sub>t−1</sub>(1+G)", say: "Kaplan and Schoar (2005); Takahashi and Alexander (2002).", where: "games2.py irr, ks_pme, yale_model" },
    ] },
    { group: "Bonds", items: [
      { name: "Price", f: "<var>P</var> = Σ<sub>k=1..n</sub> 100 · (<var>c</var>/2) · (1 + <var>y</var>/2)<sup>−k</sup> + 100 · (1 + <var>y</var>/2)<sup>−n</sup>, &nbsp; <var>n</var> = 2<var>T</var>", say: "Semiannual coupons discounted at the yield. Every bond on the site is repriced this way, never approximated.", where: "bonds.py · Bond calculator" },
      { name: "Duration and convexity", f: "<var>D</var> = [<var>P</var>(<var>y</var>−<var>h</var>) − <var>P</var>(<var>y</var>+<var>h</var>)] / (2<var>Ph</var>), &nbsp; <var>C</var> = [<var>P</var>(<var>y</var>+<var>h</var>) + <var>P</var>(<var>y</var>−<var>h</var>) − 2<var>P</var>] / (<var>Ph</var><sup>2</sup>), &nbsp; <var>h</var> = 1bp", say: "Central differences around the yield. Price change ≈ −<var>D</var>Δ<var>y</var> + ½<var>C</var>(Δ<var>y</var>)<sup>2</sup>.", where: "bonds.py · Bond calculator" },
      { name: "DV01", f: "DV01 = <var>D</var> × (<var>P</var>/100) × Face × 0.0001", say: "Dollars per basis point. Bills use <var>D</var> = <var>t</var>/(1 + <var>yt</var>).", where: "Bond calculator · Duration menu" },
      { name: "TLT proxy", f: "one 25.8-year bond, coupon solved so <var>D</var> = 15.5; return = <var>P</var>(<var>y</var><sub>0</sub>+Δ<var>y</var>)/<var>P</var>(<var>y</var><sub>0</sub>) − 1", say: "TLT's weighted maturity and duration, repriced exactly, so convexity is in every scenario.", where: "bonds.py · Hedge lab" },
      { name: "Bond returns from FRED", f: "<var>r</var><sub>t</sub> = <var>P</var>(<var>y</var><sub>t</sub>; 20 − Δ<var>t</var>, <var>c</var> = <var>y</var><sub>t−1</sub>)/100 − 1", say: "Buy a 20-year par bond at yesterday's yield, reprice it at today's. Builds bond returns back to 1993.", where: "bonds.py · macro.py" },
    ] },
    { group: "Curve", items: [
      { name: "Par interpolation", f: "monotone cubic (PCHIP, Fritsch-Carlson) between tenors; flat beyond the 1-month and 30-year points", say: "No overshoot between tenors. Linear interpolation would put a kink at every tenor and turn the forward curve into a saw.", where: "curve.py · math.js parAt" },
      { name: "Bootstrap", f: "DF(<var>t</var>) = [1 − (<var>c</var>/2) Σ<sub>j&lt;t</sub> DF(<var>j</var>)] / (1 + <var>c</var>/2), &nbsp; bills: DF(<var>t</var>) = (1 + <var>y</var>/2)<sup>−2<var>t</var></sup>", say: "Each par bond must price at 100, which pins down one new discount factor per half year.", where: "curve.py · Forwards" },
      { name: "Zero and forward rates", f: "<var>z</var>(<var>t</var>) = 2[DF(<var>t</var>)<sup>−1/(2<var>t</var>)</sup> − 1], &nbsp; <var>f</var>(<var>t</var><sub>1</sub>,<var>t</var><sub>2</sub>) = 2[(DF(<var>t</var><sub>1</sub>)/DF(<var>t</var><sub>2</sub>))<sup>1/(2(<var>t</var><sub>2</sub>−<var>t</var><sub>1</sub>))</sup> − 1]", say: "The 5y5y forward is <var>f</var>(5, 10).", where: "curve.py · Forwards" },
      { name: "Carry and roll-down", f: "<var>R</var> = [<var>P</var>(<var>y</var><sub>T−1</sub>; <var>T</var>−1, <var>c</var>) − 100]/100 + (<var>c</var> − <var>r</var><sub>repo</sub>); breakeven Δ solves <var>R</var>(Δ) = 0", say: "One year, curve unchanged, financed at the 3-month bill. The breakeven is the yield rise the position can absorb.", where: "curve.py · Carry table" },
      { name: "Futures DV01", f: "DV01<sub>fut</sub> ≈ DV01<sub>CTD</sub> / CF, &nbsp; CF = <var>P</var>(6%; <var>T</var> rounded down to a quarter, <var>c</var>)/100", say: "The cheapest to deliver is taken as the shortest deliverable, right while yields sit below 6%.", where: "curve.py · Futures hedge" },
    ] },
    { group: "Options", items: [
      { name: "Black-Scholes with dividends", f: "<var>d</var><sub>1</sub> = [ln(<var>S</var>/<var>K</var>) + (<var>r</var> − <var>q</var> + σ<sup>2</sup>/2)<var>T</var>] / (σ√<var>T</var>), &nbsp; <var>d</var><sub>2</sub> = <var>d</var><sub>1</sub> − σ√<var>T</var>", say: "Call = <var>Se</var><sup>−<var>qT</var></sup><var>N</var>(<var>d</var><sub>1</sub>) − <var>Ke</var><sup>−<var>rT</var></sup><var>N</var>(<var>d</var><sub>2</sub>); put = <var>Ke</var><sup>−<var>rT</var></sup><var>N</var>(−<var>d</var><sub>2</sub>) − <var>Se</var><sup>−<var>qT</var></sup><var>N</var>(−<var>d</var><sub>1</sub>).", where: "options.py · Option pricer" },
      { name: "Greeks", f: "Δ<sub>call</sub> = <var>e</var><sup>−<var>qT</var></sup><var>N</var>(<var>d</var><sub>1</sub>), &nbsp; Γ = <var>e</var><sup>−<var>qT</var></sup>φ(<var>d</var><sub>1</sub>)/(<var>S</var>σ√<var>T</var>), &nbsp; vega = <var>Se</var><sup>−<var>qT</var></sup>φ(<var>d</var><sub>1</sub>)√<var>T</var>/100", say: "Vega per volatility point, theta per calendar day. On the page the normal CDF uses Marsaglia's series, accurate to about 1e−15; the engine uses SciPy.", where: "options.py · Option pricer" },
      { name: "Put-call parity", f: "<var>C</var> − <var>P</var> = <var>Se</var><sup>−<var>qT</var></sup> − <var>Ke</var><sup>−<var>rT</var></sup>", say: "Checked in the tests for every strike and tenor.", where: "tests/test_curve_and_options.py" },
      { name: "Implied volatility", f: "σ<sub>imp</sub>: BS(σ) = market price, by bisection on [0.0001, 5]", say: "Returns nothing when the price breaks the no-arbitrage bounds.", where: "options.py · Option pricer" },
      { name: "Tail budget", f: "yearly cost = premium × (365/tenor) × notional; payout = notional × max(<var>K</var> − <var>S</var><sub>T</sub>, 0)", say: "Puts rolled at a fixed moneyness on the whole book.", where: "Tail-hedge budget" },
    ] },
    { group: "Hedging and regime", items: [
      { name: "Minimum-variance hedge", f: "<var>h</var>* = −Cov(<var>r</var><sub>book</sub>, <var>r</var><sub>hedge</sub>) / Var(<var>r</var><sub>hedge</sub>), &nbsp; long-only: max(0, <var>h</var>*)", say: "At <var>h</var>*, the variance removed is exactly ρ<sup>2</sup>.", where: "hedge.py · Engine readout" },
      { name: "EWMA covariance", f: "λ = 0.5<sup>1/<var>H</var></sup>, &nbsp; Cov<sub>t</sub> = λ Cov<sub>t−1</sub> + (1 − λ) <var>x</var><sub>t</sub><var>y</var><sub>t</sub>, &nbsp; <var>H</var> = 63 days", say: "Recent days weigh more; a quarter's half-life.", where: "regime.py" },
      { name: "Regime with hysteresis", f: "hedging once ρ ≤ −0.10, until ρ &gt; 0; amplifying once ρ ≥ +0.10, until ρ &lt; 0; otherwise neutral", say: "The bond hedge is held only in the hedging state.", where: "regime.py · Signals" },
      { name: "Equity futures hedge", f: "contracts = Book × β × share / (index level × multiplier)", say: "NQ is $20 per Nasdaq-100 point, MNQ $2.", where: "Futures hedge" },
      { name: "Rates futures hedge", f: "contracts = Notional × <var>D</var> × 0.0001 / DV01<sub>contract</sub>", say: "Replicates a TLT hedge for margin instead of cash.", where: "hedge.py · Futures hedge" },
    ] },
    { group: "Volatility and sizing", items: [
      { name: "GARCH(1,1)", f: "σ<sup>2</sup><sub>t</sub> = ω + α ε<sup>2</sup><sub>t−1</sub> + β σ<sup>2</sup><sub>t−1</sub>", say: "Volatility clusters and mean-reverts; HAR-RV and EWMA run beside it.", where: "vol.py" },
      { name: "Volatility target", f: "<var>L</var> = σ<sub>target</sub> / σ̂", say: "20% target by default.", where: "sizing.py · Sizing lab" },
      { name: "Kelly as an edge check", f: "<var>f</var>* = (μ − <var>r</var>) / σ<sup>2</sup>; at fraction <var>k</var>, leverage <var>L</var> needs μ − <var>r</var> = <var>L</var>σ<sup>2</sup>/<var>k</var>", say: "A 32%-volatility book at 1.5x needs about 15% a year over cash at full Kelly, 61% at quarter Kelly.", where: "sizing.py · Sizing lab" },
      { name: "Drawdown cap", f: "largest <var>L</var> with the <var>q</var>-quantile of one-year max drawdown ≤ limit", say: "2,000 simulated years on the page (4,000 in sizing.py), rebalanced daily, borrowing at cash plus a spread. Size to run = min(vol target, drawdown cap, gross limit).", where: "sizing.py · Sizing lab" },
    ] },
    { group: "Market reads", items: [
      { name: "What moved", f: "Δ<sub>w</sub> = <var>x</var><sub>t</sub> − <var>x</var><sub>t−7d</sub> (yields, spreads, volatility) or ln(<var>P</var><sub>t</sub>/<var>P</var><sub>t−7d</sub>) (prices); &nbsp; <var>z</var> = (Δ<sub>w</sub> − mean)/sd over every seven-day change in three years", say: "Unusual means 2σ or more. Overlapping weeks give a large sample; fat tails make 2σ weeks more common than one in 22.", where: "marketstate.py · What moved" },
      { name: "Realized volatility", f: "σ<sub>21</sub> = sd(ln <var>P</var><sub>t</sub>/<var>P</var><sub>t−1</sub>, last 21 days) × √252 × 100", say: "Close to close, in the same volatility points as VIX and VXN.", where: "marketstate.py · Is insurance cheap?" },
      { name: "Volatility risk premium", f: "VRP<sub>t</sub> = IV<sub>t</sub> − σ<sub>21,t</sub>; &nbsp; earned<sub>t</sub> = IV<sub>t</sub> − σ<sub>21,t+21</sub>", say: "The first compares today's price with the past month; the second with the month the option covered, which is what sellers actually earn.", where: "marketstate.py · Is insurance cheap?" },
      { name: "VIX term structure", f: "VIX / VIX3M; above 1 the curve is inverted", say: "Near-term fear priced above three-month fear.", where: "marketstate.py · Signals" },
      { name: "Net liquidity", f: "(WALCL − WTREGEN − 1,000 × RRPONTSYD) / 10<sup>6</sup>, in $ trillions", say: "Weekly on the Fed's Wednesday balance sheet; WALCL and WTREGEN are in millions, reverse repo in billions, taken on the same day.", where: "marketstate.py · Liquidity" },
      { name: "Funding gap", f: "SOFR − IORB, in basis points; the signal uses the five-day average", say: "Above zero, repo pays more than reserves: cash is scarce.", where: "marketstate.py · Signals" },
      { name: "Desk read", f: "score(playbook) = Σ<sub>signals</sub> [2 if red, 1 if amber or a mapped green]; closest = highest score, at least 3", say: "A tally, not a model: it says which playbook the evidence argues for, and the reader decides.", where: "views.js · Signals" },
    ] },
    { group: "Risk and validation", items: [
      { name: "VaR and expected shortfall", f: "VaR<sub>99</sub> = −quantile<sub>1%</sub>(<var>r</var>), &nbsp; ES = −mean(<var>r</var> | <var>r</var> ≤ −VaR); FHS: <var>r̃</var><sub>t</sub> = <var>r</var><sub>t</sub> · σ̂<sub>today</sub>/σ̂<sub>t</sub>", say: "Filtered history makes VaR respond to today's volatility.", where: "risk.py · Engine readout" },
      { name: "Probabilistic Sharpe", f: "PSR = Φ[(SR − SR*) √(<var>n</var>−1) / √(1 − γ<sub>3</sub>SR + (γ<sub>4</sub>−1)SR<sup>2</sup>/4)]", say: "SR per period; γ<sub>3</sub> skew, γ<sub>4</sub> kurtosis.", where: "metrics.py" },
      { name: "Deflated Sharpe", f: "SR* = √V[SR] · [(1 − γ)Φ<sup>−1</sup>(1 − 1/<var>N</var>) + γΦ<sup>−1</sup>(1 − 1/(<var>Ne</var>))], &nbsp; γ ≈ 0.5772", say: "The Sharpe the best of <var>N</var> skill-less trials would show by luck. Above 0.95 is the bar.", where: "metrics.py · Engine readout" },
      { name: "Forecast skill", f: "Brier = mean[(<var>p</var> − <var>y</var>)<sup>2</sup>], &nbsp; skill = 1 − Brier/Brier<sub>base rate</sub>", say: "A model must beat always forecasting the base rate, out of sample.", where: "signals.py" },
     ] },
    { group: "Decisions and research (v0.5)", items: [
      { name: "Velocity, acceleration, time to trigger", f: "<var>v</var><sub>13</sub> = OLS slope of the last 13 weeks, per week; <var>a</var> = <var>v</var><sub>13</sub>(<var>t</var>) − <var>v</var><sub>13</sub>(<var>t</var> − 13); <var>T</var> = (<var>L</var><sup>*</sup> − <var>L</var>)/<var>v</var> when sign(<var>v</var>) = sign(<var>L</var><sup>*</sup> − <var>L</var>)", say: "Monthly series use a four-print (three-month) slope and the one-month change. Price series are sloped in logs.", where: "roc.py · Decide desk" },
      { name: "Confidence and fragility", f: "conf = ∏ <var>p</var><sub>i</sub> over a call's assumptions; fragility<sub>i</sub> = (1 − <var>p</var><sub>i</sub>) × impact<sub>i</sub>", say: "A product assumes independence; correlated assumptions fail together, so it is a floor on the risk.", where: "decisions.py · Decide desk" },
      { name: "Kelly on a position", f: "<var>f</var><sup>*</sup> = <var>p</var>/<var>l</var> − (1 − <var>p</var>)/<var>w</var>, &nbsp; growth <var>g</var> = <var>p</var> ln(1 + <var>fw</var>) + (1 − <var>p</var>) ln(1 − <var>fl</var>)", say: "Win <var>w</var> or lose <var>l</var> per unit of position. The desk caps size at a quarter of <var>f</var><sup>*</sup>.", where: "decisions.py · Journal" },
      { name: "Luck against skill", f: "P(≥<var>k</var> of <var>n</var> | ½) = Σ<sub>i≥k</sub> C(<var>n</var>,<var>i</var>)/2<sup><var>n</var></sup>; &nbsp; alpha<sub>i</sub> = <var>r</var><sub>i</sub> − β<sub>i</sub><var>r</var><sub>bench</sub>; &nbsp; <var>n</var><sub>needed</sub> = (2·sd/mean)<sup>2</sup>", say: "Process (four checks) and outcome (alpha) are scored separately, so luck shows up as its own quadrant.", where: "decisions.py · Journal" },
      { name: "The hedge line", f: "ρ<sub>36</sub>(stocks, bonds) bucketed by π<sub>36</sub>; cut <var>c</var> maximizes share(ρ&lt;0 | π&lt;<var>c</var>) − share(ρ&lt;0 | π≥<var>c</var>); line = low edge of the cuts within 1 point of the best", say: "Monthly S&amp;P 500 total return against a constant-maturity 10-year bond, 1871 on; months filled on a full calendar.", where: "research.py · Findings" },
      { name: "Months to the line", f: "first <var>k</var> with (CPI<sub><var>t</var>+<var>k</var></sub>/CPI<sub><var>t</var>+<var>k</var>−36</sub>)<sup>1/3</sup> − 1 &lt; line, with CPI growing 2% a year after <var>t</var>", say: "Base effects included: the months that roll out of the average are the real ones.", where: "marketstate.py · Decide desk" },
      { name: "Depreciation vintages", f: "<var>D</var><sub>t</sub> = Σ<sub>v</sub> <var>C</var><sub>v</sub>[<var>s</var>·ov(<var>t</var>,<var>v</var>,<var>L</var><sub>s</sub>)/<var>L</var><sub>s</sub> + (1−<var>s</var>)·ov(<var>t</var>,<var>v</var>,25)/25], &nbsp; <var>s</var> fitted to reported <var>D</var>", say: "Each year's capex enters service mid-year; ov is the overlap of year <var>t</var> with the asset's life.", where: "fundamentals.py · Fundamentals" },
      { name: "Minsky stage", f: "hedge if capex ≤ OCF; Ponzi edge if OCF ≤ 0 or operating income &lt; interest; otherwise speculative", say: "Latest-quarter income and interest are used when the annual figures hide a recent turn.", where: "fundamentals.py · Fundamentals" },
      { name: "Compound growth with a hedge", f: "<var>g</var> = exp(Σ<sub>s</sub> <var>p</var><sub>s</sub> ln(1 + <var>r</var><sub>s</sub> − <var>c</var> + <var>h</var><sub>s</sub>)) − 1", say: "Spitznagel's test: own the hedge only if <var>g</var> rises.", where: "decisions.py · Swans" },
      { name: "Watts from dollars", f: "GW = capex/cost per GW; TWh = GW × 8,760 × load/1,000; share = TWh/4,000", say: "4,000 TWh is implied by LBNL's 176 TWh = 4.4% for 2023.", where: "Physics desk" },
    ] },
    { group: "Brain, trading and the field manual (v0.6)", items: [
      { name: "Propagation by order", f: "<var>x</var><sub>k</sub> = <var>W</var>&#8868;<var>x</var><sub>k−1</sub>; total = Σ<sub>k≤K</sub> <var>x</var><sub>k</sub> → [(<var>I</var> − <var>W</var>&#8868;)<sup>−1</sup> − <var>I</var>]<var>x</var><sub>0</sub> when ρ(<var>W</var>) &lt; 1", say: "Eleven links measured by recursive regression on standardized monthly changes per regime; the rest judged. 400 Monte Carlo draws over every link's uncertainty.", where: "brain.py · The brain" },
      { name: "Avellaneda-Stoikov quotes", f: "<var>r</var> = <var>s</var> − <var>q</var>γσ<sup>2</sup>τ, &nbsp; δ = γσ<sup>2</sup>τ + (2/γ) ln(1 + γ/<var>k</var>)", say: "Fills at rate <var>A</var>e<sup>−<var>k</var>δ</sup>; the simulator compares the skewed quoter with a symmetric one on the same paths.", where: "microstructure.py · Market making" },
      { name: "Square-root impact and Almgren-Chriss", f: "<var>I</var> = <var>Y</var>σ√(<var>Q</var>/ADV); &nbsp; <var>x</var><sub>j</sub> = <var>X</var> sinh(κ(<var>T</var> − <var>t</var><sub>j</sub>))/sinh(κ<var>T</var>)", say: "Linear temporary impact is calibrated so the even pace costs exactly the square-root impact.", where: "microstructure.py · Market making" },
      { name: "Hedge selector", f: "ES<sub>5%</sub>(book) − ES<sub>5%</sub>(book + 0.3·hedge), per regime; ratio to yearly carry when carry is a cost", say: "Regimes: 36-month inflation above or below 2.75%, the low edge of the 2.75% to 4.25% band (the validated line is 4.25%).", where: "buyside.py · Buyside 2026" },
      { name: "Student-t shortfall", f: "ES<sub>α</sub> = −[μ − <var>s</var> · <var>f</var><sub>ν</sub>(<var>t</var><sub>α</sub>)/(1 − α) · (ν + <var>t</var><sub>α</sub><sup>2</sup>)/(ν − 1)]", say: "ν, μ and <var>s</var> fitted by maximum likelihood; compared with the normal model and history at 97.5%.", where: "buyside.py · Buyside 2026" },
      { name: "Private credit net yield", f: "net = (base + spread − PD·(1 − R) − mgmt)·(1 − incentive)", say: "Reproduces the manual's table: about 6.4% at 2% defaults, 4.5% at 6%, negative at 14%.", where: "accounting.py · Buyside 2026" },
      { name: "Feed heat and skew", f: "heat = (<var>n</var><sub>24h</sub> − μ<sub>28</sub>)/max(σ<sub>28</sub>, √(μ<sub>28</sub> + 1)); skew = share<sub>niche</sub>(theme, 72h) − share<sub>niche</sub>(all)", say: "Lead time: the lag of peak cross-correlation between niche and mainstream counts.", where: "feeds.py · Noteworthy" },
    ] },
  ];

  const FAQ = [
    { g: "Start here: the engine in plain English", q: "What is this site, in one sentence?", a: "A research tool that watches the markets an AI-heavy stock portfolio depends on, tests what traders believe with real data, and says, with its reasons and its doubts, whether to hold, hedge or change anything; a person makes every decision." },
    { g: "Start here: the engine in plain English", q: "Is this my portfolio?", a: "No. Every number about holdings is a model book (Microsoft, Amazon, Alphabet, Meta, Nvidia, Broadcom, Tesla, SpaceX, Oracle and hedges such as long Treasuries). Real positions live in a private file that is never put on the page or in the code." },
    { g: "Start here: the engine in plain English", q: "What is the brain?", a: "A map of how markets push on each other: oil on inflation, inflation on interest rates, rates on tech stocks, and so on. The atlas part learns those pushes from decades of monthly data; the core part writes down judgments the data cannot measure yet, and labels them as judgments." },
    { g: "Start here: the engine in plain English", q: "How does the engine decide, in one sentence?", a: "Every month it reads 156 years of market data, works out what kind of market this is, estimates what the next year is likely to pay, chooses how much stock a cautious investor would hold given that, and then trusts its own answer only as far as its track record since 1940 has earned. The How it works desk says the same in a paragraph and a page, and replays any month since 1940." },
    { g: "Start here: the engine in plain English", q: "What is the engine? And the mind, the brain, the parameters?", a: "One system, the engine, in layers. Its parameters (Theta) are the numbers it has learned from data: regime transition matrices, regression and network weights, model-averaging weights, a Q-table, a causal map and a knowledge graph, 22 objects shaped by stated optimisers, inventoried on the Parameters desk. The knowledge graph (the mind) is the layer that holds what the system knows, 9,435 nodes with typed links, and answers questions by a walk over it. The causal map (the brain) is the layer that says where a shock travels. The decision and portfolio engines are the layers that turn beliefs into a sized call. Nothing on the site is a separate brain; every desk reads the same parameters." },
    { g: "Start here: the engine in plain English", q: "What is the mind, and how is it different from the brain?", a: "Both are layers of the one engine. The mind is the knowledge graph: 4,575 ideas (like the P/E ratio or a margin call), the 72 measured markets, 581 facts and research papers with their sources, 267 investor quotes, 213 economies, every month since 1871, every part of the engine's code, its 22 parameter objects and 159 pieces of evidence that point one way or the other. The brain is the causal map: 34 parts of the financial system and the signed links between them. The brain shows how a shock travels; the mind answers questions." },
    { g: "Start here: the engine in plain English", q: "What is a node? What is a link?", a: "A node is one thing the mind knows: an idea, a market, a fact, a quote, a country, a piece of code. A link joins two nodes and says how: one is a kind of the other, one measures the other, one causes the other to rise or fall, a fact is evidence about an idea, a quote was said by an investor. There are 9,435 nodes and about 37,900 links: 4,575 concepts, 1,870 months of market history, 872 sourced facts and papers, 371 quotes, 503 companies and the engine itself." },
    { g: "Start here: the engine in plain English", q: "What happens when I type a question into Think?", a: "Eight steps, in a fraction of a second. It finds the nodes your words name, lets attention spread outward along the links, picks the claim your question is really about, adds up the evidence for and against it, checks how much the answer depends on any one kind of evidence, traces how the answer would reach the portfolio, and says what it would do. Every step is shown." },
    { g: "Start here: the engine in plain English", q: "What does 'spreading activation' mean?", a: "Imagine dropping ink on the words you asked about and letting it seep along the links for 40 steps, with three quarters flowing on and a quarter returning to where it started each step. Ideas close to your question, or connected to it many ways, end up darkest. The gold glow on the picture is that ink." },
    { g: "Start here: the engine in plain English", q: "What is a 'claim', and why does the mind sometimes answer a slightly different question?", a: "The mind can only weigh claims it has evidence for: 18 big debates investors argue about (is AI a bubble, are stocks overvalued, are bonds a hedge) and seven questions of the form 'does this method actually work?'. It picks the one your question lights up most and tells you which it chose. If you ask about something it has no evidence on, it says so instead of guessing." },
    { g: "Start here: the engine in plain English", q: "What do the percentages mean?", a: "How likely the claim is, given only the evidence the mind has, weighted by how reliable each kind of evidence has proved. 50% means the evidence is balanced. The shaded range shows how far the answer moves if any one family of evidence is thrown out: a wide range means the answer leans on one thing." },
    { g: "Start here: the engine in plain English", q: "What are 'log-odds', and why use them?", a: "A way of adding up evidence. Odds of 1 to 1 are a log-odds of zero; each piece of evidence adds or subtracts a little; the total turns back into a probability at the end. It keeps two strong pieces of evidence from producing more than 100% and lets weak evidence count a little instead of nothing." },
    { g: "Start here: the engine in plain English", q: "Why does repeating the same fact not make the answer more certain?", a: "Because ten articles quoting one number should not count ten times. Evidence from the same family (several valuation ratios, say) is discounted: the strongest counts fully, the second 71%, the third 58%, and so on, so ten restatements count about five times one reading, not ten." },
    { g: "Start here: the engine in plain English", q: "What is 'the hinge'?", a: "The one piece of evidence the answer depends on most. The mind shows what the answer would be without it. If the hinge is doubted, the size of its effect on the answer is already known." },
    { g: "Start here: the engine in plain English", q: "Do the investor quotes decide the answer?", a: "Barely. Opinion counts as one low-reliability signal, because famous investors disagree with each other and are often early or wrong. The quotes are there so you can hear the best case on each side in the investors' own words, each linked to where it was said." },
    { g: "Start here: the engine in plain English", q: "Does the engine trade?", a: "No. It can write a trade proposal with a reason and a 'kill criterion' (what would prove it wrong), stamp it with a fingerprint so it cannot be altered, and check it against the portfolio's limits. A person reads it and, if they agree, places it themselves in their own brokerage. Nothing here can place, change or cancel an order." },
    { g: "Start here: the engine in plain English", q: "What is MCP?", a: "The Model Context Protocol: a standard way for an AI assistant to call tools. The engine offers 33 tools (ask the mind, read the labs, run the poker and bargaining math, trace a shock, check a hedge, write a proposal). An assistant connected to it can research for you; it still cannot trade." },
    { g: "Start here: the engine in plain English", q: "What is a moving average, and does the 200-day one work?", a: "The average price over the last 200 trading days (about ten months); when the price is above it, many traders call the trend up. On 156 years of US stocks, a rule of holding only above the 10-month average cut the worst loss from about 77% to 48% but earned less than simply holding, and once you account for trying 22 different lengths, there is no reliable extra return. It is insurance, not a money machine." },
    { g: "Start here: the engine in plain English", q: "What is RSI, and does 'overbought' mean it will fall?", a: "The Relative Strength Index compares recent gains with recent losses on a 0 to 100 scale; above 70 is called overbought. In the labs' tests most overbought and oversold signals do not survive once you correct for testing many signals at once. A high RSI often means a strong trend, which tends to continue for a while." },
    { g: "Start here: the engine in plain English", q: "What is the P/E ratio, and what is CAPE?", a: "P/E is the price of a share divided by a year of its earnings: how many years of today's profit you pay for. CAPE uses ten years of inflation-adjusted earnings so one good or bad year does not distort it. CAPE near 41 today is higher than in 99% of months since 1881. History says that means low returns over the next decade, but almost nothing about next year." },
    { g: "Start here: the engine in plain English", q: "If stocks are so expensive, why not sell everything?", a: "Because expensive markets can stay expensive for years, and the evidence that valuation predicts next year's return is close to zero. The same tests that say 'low decade returns' say 'no timing signal'. The mind weighs both, which is why its verdicts are rarely extreme." },
    { g: "Start here: the engine in plain English", q: "What does 'statistically significant' mean, and why do you keep correcting it?", a: "A result is called significant if luck alone would rarely produce it. But test 34 ideas and a few will look significant by luck. The labs list every test in one table and apply two standard corrections; of 34 tests, 15 pass before correction and 8 after the strictest one." },
    { g: "Start here: the engine in plain English", q: "What is backtest overfitting?", a: "Trying many rules on the same history until one looks brilliant. It usually disappoints afterwards. The engine guards against it by testing every variant, judging the best against the best that luck would produce, and reporting results on data the rule was not built on." },
    { g: "Start here: the engine in plain English", q: "Why does the engine care about poker and haggling?", a: "Because trading is betting under uncertainty against people who may know more. Poker teaches pricing a bet against the pot, sizing so a bad run cannot wipe you out, and judging decisions by their odds rather than the result; trading firms use it to train staff. Haggling teaches anchoring and walk-away prices, which is how block trades and private deals are priced." },
    { g: "Start here: the engine in plain English", q: "What is the Kelly criterion?", a: "A formula for how much of your money to bet when you have an edge: edge divided by the odds. Bet more than twice that and you will, in the long run, lose even with an edge. Most professionals bet half of it, which keeps about three quarters of the growth with far smaller swings." },
    { g: "Start here: the engine in plain English", q: "What is backwardation, and why does it matter for oil?", a: "When oil for delivery now costs more than oil for delivery later. It happens when barrels are scarce today. In mid-October, physical Brent near $134 sat far above futures near $107, a sign that supply is still tight even as the forecasters expect prices to fall." },
    { g: "Start here: the engine in plain English", q: "What do private equity and venture capital have to do with this portfolio?", a: "They are where a lot of AI money sits before it reaches the stock market. 82.7% of US venture dollars this year went to AI. Buyers of stakes in private funds are paying about 87% of the funds' own valuations, which suggests those valuations are generous. Stress there can spill into credit and into the hyperscalers' customers." },
    { g: "Start here: the engine in plain English", q: "Where do the numbers come from, and how do I know they are real?", a: "Each one links to its source. knowledge.json holds 780 checked items (facts, papers, definitions and source profiles), gathered by research agents across versions; each was confirmed on its source page, and from v0.14 on a second set of agents reopened every page without seeing the first agents' notes (in v0.14: 233 confirmed, 35 corrected, none failed). A figure that could not be verified, such as a quote from a post that could not be opened, is credited as an idea and not quoted. Market data comes from public sources (FRED, the SEC, public datasets) through a daily run." },
    { g: "Start here: the engine in plain English", q: "What are agents and subagents?", a: "Copies of Claude given one narrow job each. The lead agent writes the code and the page; subagents run at the same time to research one topic or check another agent's work, then hand back a report. Their reports are treated as data to check, not as orders. The Agents page in Methods has the details." },
    { g: "Start here: the engine in plain English", q: "Can I read the code?", a: "Yes. The Under the hood page in Methods shows 68 of the engine's files as they shipped with this version, with a search box, and walks through how a question turns into a proposal a person approves." },
    { g: "Start here: the engine in plain English", q: "What should I not trust here?", a: "Anything labelled judged or hypothesis, numbers marked secondary, and any verdict whose range is wide. The mind only knows what is in its graph; it has no evidence on China or bitcoin beyond investor opinion, and says so. History can break: the stock-bond relationship flipped in 2022." },
    { g: "Start here: the engine in plain English", q: "How often does it update?", a: "A GitHub Action runs every weekday: it fetches public data, reruns every engine and records what each read and wrote. The research facts are refreshed by hand with the agent process described above, so their dates are shown." },
    { g: "Start here: the engine in plain English", q: "What is the single most useful thing to do with it?", a: "Ask it the question you are most sure about, read the strongest argument against you in the 'Against it' column, and look at what would change the view. If you cannot say why the hinge is wrong, size the position as if you might be." },
    { g: "Start here: the engine in plain English", q: "What is the technicals and fundamentals desk?", a: "Technical analysis, tested: about thirty indicators, today's readings, support and resistance, and for each of thirteen chart signals, how it actually did on that asset's own history, with a correction for testing many signals at once. Fundamental analysis, sourced: ratios and the Piotroski, Altman and Beneish scores computed from the company's own SEC filings, with every tag named." },
    { g: "Start here: the engine in plain English", q: "Do chart signals work?", a: "On the series tested here, mostly not in the direction the textbook says, and the answer differs by asset. Natural gas and the VIX mean-revert, so trend signals lose on them and fade signals win. Each signal's weight in the composite is set by its own track record on that asset, so one that never worked counts for nothing." },
    { g: "Start here: the engine in plain English", q: "What is reinforcement learning, and did it help?", a: "A method that learns a policy (here, how much stock to hold each month) by trying actions against the record and keeping what earned the most. Retrained every year since 1940 and judged on years it had not seen, it did not beat simply holding, and the plain 10-month trend rule beat both on a risk-adjusted basis." },
    { g: "Start here: the engine in plain English", q: "Can the engine see my Robinhood account?", a: "Not directly: Claude's connector directory has no Robinhood connector today. Export your positions as a CSV and drop it on the Technicals and fundamentals desk (it is read in your browser and sent nowhere), run python -m buildout positions export.csv on your machine, or pass the weights to the MCP tool analyze_positions from any assistant that can read the account." },
    { g: "Start here: the engine in plain English", q: "Why is distribution called the new moat?", a: "Because a good AI feature can be copied in months, but the path to the customer cannot: Microsoft's Copilot seats, Google's Gemini users and Meta's daily users receive a new model on day one. The Edge desk lists what each company discloses, checked on its own page, with the counter-argument that generative AI may have no lasting moats at all." },
    { g: "v0.30", q: "Why did the Desk's call change from 1.00x to about 0.59x?", a: "Nothing about the market changed; the measurement did. The decision engine models the S&P 500 and finds no evidence for any size but holding, so it says 1.00x of the index. The book is nine AI names with a Nasdaq-100 beta above 1.2. Measured on their own daily prices, the book at 1.00x runs about 27% volatility, a worst month in twenty of about 17% and a one-year drawdown of about 41% at the 95th percentile, against limits of 20%, 12% and 25%. The tightest limit, the drawdown cap, allows about 0.59x. The alternative that keeps every name is a Nasdaq-100 futures short of about 86% of NAV." },
    { g: "v0.30", q: "Does the long bond hedge this book?", a: "Not on the evidence. Walked forward on the book's own days since 2017, a long 20-year bond held only when its correlation said it would hedge cut the book's variance about 3% and made 2022 worse; a standing 30% bond did nothing. A Nasdaq-100 short at the measured beta cut the variance about 90% and turned 2022 from a 42% loss to flat, at the cost of the index's return in the years it rose. On the book's worst days since 2022 the bond rose only about half the time." },
    { g: "v0.29", q: "What is the futures engine?", a: "A test of the best known futures premia across 39 liquid CME futures: carry (what holding a future earns if prices stand still), trend over 1, 3 and 12 months, basis momentum and, where the CFTC's site is reachable, hedgers' positioning. Each signal is a portfolio across markets and one over time, net of trading and roll costs, and must pass a multiple-testing cut, beat a passive long portfolio of the same markets, hold in both halves of the record, hold within asset classes and still pay since it was published. It also reads the book's hedge: what the Treasury futures pay to hold today and how they did in the months stocks fell most." },
    { g: "v0.29", q: "Where do the futures prices come from?", a: "Two sources, run separately. The long record uses pysystemtrade's published prices (Rob Carver's open-source project): each day's held contract and the next one, from the 1970s or 1980s to March 2024, reachable from the workspace where the engine is built. The recent record uses your Databento key for CME Globex daily bars and contract definitions from 2010 to now; it refuses any pull estimated above $5 and runs on your computer or in the weekly GitHub workflow." },
    { g: "v0.28", q: "What is the filings engine?", a: "A broad test of what companies and their insiders file with the SEC. It covers every stock in the S&P 500 at each month end from 2009, about five hundred a month, including the ones that later left. The signals: insiders' open-market purchases and sales (net buying, cluster buying, buying by insiders who do not trade on a routine calendar, buying by the chief executive or financial officer); accruals, gross profitability, asset growth, share issuance, earnings surprise and revenue acceleration from the numbers in each 10-K and 10-Q; and, optionally, how much a 10-K's words changed from the year before. A value is used in a month only if it was filed before that month's last trading day. Breadth is the point: a small edge across five hundred stocks a month is measurable where an edge on fifteen is not, though stocks that share an industry are not separate bets, and the test is built to count that." },
    { g: "v0.28", q: "Why does the Filings desk say the first run is pending?", a: "Because the SEC's site cannot be reached from the workspace where the engine is built. The first real run has to happen where it can: on your computer (python -m buildout filings --ua with your name and email) or in GitHub (the filings-run workflow, weekly or by hand, once the SEC_USER_AGENT variable is set). It downloads the data once and caches it. Until then the desk shows the design, the engine's validation on synthetic data, where it found a planted edge of realistic size, and its calibration across synthetic worlds with no edge." },
    { g: "v0.28", q: "Why not just shuffle which company each signal belongs to?", a: "That shortcut, a reassignment permutation, keeps each signal's persistence but forgets that stocks share industries and factors. A signal that leans toward one industry has an IC that rises and falls with that industry from month to month, and the shuffle hides that swing, so it calls noise significant. An independent audit caught this in the first design; the engine now takes its p-value from the monthly IC series itself, and the Filings desk shows both tests side by side on random factor tilts." },
    { g: "v0.27", q: "What is the nowcast?", a: "A forecast of each holding's next quarterly report from facts published before it. TSMC reports revenue every month, by the 10th; American companies report a quarter at a time, weeks later. So TSMC's figures, the hyperscalers' capital spending and the reports of peers that go first are all public before NVIDIA, Broadcom or Microsoft report. The nowcast predicts the change in each company's revenue growth from them, trained only on earlier reports, and is scored against the simplest forecast: growth persists. The best signal, peers' recent reports, cuts the error for chip makers by about a fifth, but not by enough to pass the cut across every model tried; for now the desk shows persistence for every company." },
    { g: "v0.27", q: "Can the nowcast be traded?", a: "Not on this evidence. If the market had not finished pricing TSMC's figures, capital spending or peers' reports, they would predict the stock's move on report day or the drift after it. 51 hypotheses were tested against 240 placebo signals: none passes, and the tests could only have seen correlations of about 0.2 or more. A draft found a strong result for chip makers, but it held only when a season was drawn as the calendar quarter of the report, and vanished when drawn as the quarter reported on or the month of the report, so the engine now requires a result to hold all three ways. Large public signals on the largest companies look priced; an edge would need finer data, more companies, or both." },
    { g: "v0.27", q: "How is each report dated?", a: "By the company's earnings release: the date it was filed with the SEC (Form 8-K, Item 2.02), and where that record is missing (Tesla, releases since December 2025, Broadcom and Marvell under their former names) the date read from the company's own release, each with a source. A checker confirmed a sample of 36 of those dates against other documents, and 26 dates verified separately are all on record. The first version dated reports from trading volume, and an audit found it wrong for most quarters it had not been tuned on, so that method is gone." },
    { g: "v0.26", q: "What is the edge lab?", a: "A machine that invents trading ideas by the tens of thousands and then tries to kill them, in the spirit of finding odd, slow edges all over the world with unusual data. It applies a library of rules (momentum, value, seasonality, ranks, spreads, leads from other markets, and 89 unusual and computed series such as ocean temperatures, sunspots, storms, shipping rates and the moon) to 70 world markets: 43,247 candidates. Each must survive a multiple-testing correction calibrated on fake markets, show timing beyond drift and beyond its own parts, hold across its markets, hold in later years, cover trading costs and stay distinct. 5 survive, against fewer than 1 expected by luck." },
    { g: "v0.26", q: "Do the edges work on years they were not chosen on?", a: "The 5 main survivors cannot be tested after 2017, because their IMF commodity prices end in June 2017. So the engine replayed the whole search with data through 2010 and judged it on 2011 to June 2017: 6 edges survived, all 6 made money after costs and 5 had a t of 2 or more. Their book earned a Sharpe of 1.61 (t 3.7) at 9% volatility, and 1.58 without its best month. It is a replay, not an independent test: those years were the main search's validation years, and the results were in view when the audit changed the method. Three more cautions: the 6 are about 3 independent bets, they trade spot research prices rather than futures with roll, and the naive book of all 14 tested discovery survivors did better (1.90), so the later filters cost return in that window. Promising, not a trade." },
    { g: "v0.26", q: "What did the independent audit change?", a: "Before release an auditor reran the engine. It found no look-ahead in the code's timing, but one in the data: Shiller's interpolated early bond and dividend years inflated the long US block. It also found four faults in the evidence. The test years did not test most edges, because their markets had stopped trading. The fake signals gave no test of chance for own-history rules and composites. The p-values were 1.2 to 1.4 times too optimistic in variance. And one oil-shock month carried the book. Each was fixed in the engine. A second pass found the cut still too loose where it is used (a false share of 17%, now held at 3% on fake markets), and the replay's test years overlapping the main validation years, which the page now states. The survivors fell from 65 to 5, composites from 27 to 0 and the long US block from 6 to 0. The 0.59 book Sharpe after 2017 is gone, because no edge can be tested there. The desk shows the before and after." },
    { g: "v0.25", q: "Can the engine reason, or does it only fit numbers?", a: "It reasons four ways, and each is tested. Deduction: the policy and the mind's typed links are written as rules, forward chaining derives what must follow (892 new facts, no contradictions), and today's call is derived as a proof with the value at which each premise would flip it. Induction: it tried 31,746 conditions on data before 1961, carried the best 30 into 1961 to 2026 untouched, and 4 survived. Abduction: it ranks what best explains an outcome, labelled retrospective. Invention: it proposed 8 new regimes and 728 new predicates; none forecast better than the long-run average out of sample, and the page says so." },
    { g: "v0.25", q: "Did Taleb's and the legendary traders' rules hold up?", a: "Mostly not, as testable rules on monthly US data since 1871. Research agents translated 43 principles into conditions and outcomes, checkers verified each against its source, and the reasoner ran them all with Benjamini-Hochberg control and a split at 1950. Two hold in both halves: high inflation breaks the stock-bond hedge (Dalio), and a negative stock-bond correlation tends to persist (actuarial experience rating). Three hold in one era only (volatility persistence among them), one is reversed (Taleb's claim that quiet years hide volatility), and the rest show no evidence, including the 200-day rule, maximum pessimism and the boom phase. Many of these principles are about options, sizing and survival, which monthly index data cannot test; the Methods desk carries them as concepts." },
    { g: "v0.25", q: "What did actuaries and weather services add?", a: "A way to grade the engine. Scored like a weather forecast since 1950, its monthly predictive is calibrated (90% intervals covered 91.5%) except in the far tail, where the 1% loss is breached 1.7% of the time; backtested like an actuarial reserve since 1940, only the generalized Pareto tail is calibrated at 1%. Five borrowed upgrades were tried on the decision core (two kinds of EMOS recalibration, BMA, credibility-estimated shrinkage and an EVT floor on the loss budget); none beat it cleanly, so none was adopted, and each now counts in the gate. Ruin is reported beside the limits: a 50% fall from a peak within ten years has a 12% chance at 1x and 41% at the 1.5x cap." },
    { g: "v0.25", q: "Why is the math on by default now?", a: "So every number can be checked where it appears: Today derives the call step by step with today's values, each How it works stage shows its formula, and every method on the Methods desk shows its formula and today's number. The sigma button in the top bar hides them." },
    { g: "v0.24", q: "Why was the 0.50 trend overlay withdrawn?", a: "Because it failed the test the engine applies to itself. In v0.23 the factor was chosen on the full 1940 to 2026 record, and it passed the rule (keep holding's expected utility, cut the most drawdown) by exactly zero: a knife-edge, and an in-sample one. In v0.24 the same rule is walked forward: ten years of burn-in, then the factor re-chosen every twelve months using only the record to date. That version averaged a 0.56 scaling, changed 18 times, and cost expected utility against holding (t -2.29; Sharpe 0.60 against 0.64). So no overlay is applied; the four scalings tried now count among the 12 strategies the gate discounts, and the trend rule stays as a cross-check." },
    { g: "v0.24", q: "Which number is the book's size, when desks show several?", a: "The decision engine's gated equity exposure, today 1.00x with no bond sleeve. Every other size on the site (the volatility rule on the Decide desk, the scenario solver, the decision loop, the buyside rule, the sizing lab) now says beside itself that it is a cross-check and how far it sits from the governing size. The Today page also lists the limits in force: the 12% monthly expected-shortfall budget governs the size; the Solve desk's 15% three-month scenario limit is a stress test." },
    { g: "v0.24", q: "What is the Digest, and how is research checked?", a: "The Digest lists every knowledge item dated in the last fortnight, by the question it bears on, each with its source link and how it was checked. Research agents gather items to a fixed schema; a separate checker agent reopens every source without the researcher's reasoning and returns ok, fixed or fail. Only ok and fixed items enter the store. Of 217 checks in v0.24, 20 came back corrected and 1 failed." },
    { g: "v0.23", q: "What is Theta, and why count it?", a: "Theta is the engine's parameters: every matrix, vector and scalar an algorithm shaped by optimising a stated objective on stated data. Counting it answers two questions a fund's risk function asks first: how much has this system learned, and from what? The answer is 22 objects and about 598,000 numbers, of which the decision core is 2,850; the rest is the knowledge graph's spectral map, which compresses what the system knows rather than forecasting anything. Each object carries its shape, its optimiser, its objective, its data, its refit schedule and the desks it feeds, and the constants set by hand are listed apart so nothing hides a dial." },
    { g: "v0.23", q: "(v0.23, since withdrawn) Why was the trend overlay 0.50 rather than the classic trend rule?", a: "The classic rule (out of stocks below the 10-month average) has the best Sharpe and the shallowest drawdown since 1940, but for a risk aversion of 2.2 it gives up expected utility against holding (utility t -0.37), because it sits out months that on average pay. The engine tried five scalings of exposure below the average: 0, 0.25, 0.50, 0.75 and 1 (holding). The rule, written before the result: the deepest drawdown cut among the factors that keep holding's expected utility. That is 0.50: worst drawdown 36% against 52%, Sharpe gain 90% range +0.02 to +0.17, utility unchanged. It is an overlay on the gated call, not a replacement for it; today the trend is on, so it changes nothing." },
    { g: "v0.23", q: "Where did the Today page's sections go?", a: "To the desks that own them. The mind graph and its question box are on The mind; investor voices on Legends; the risk rings, the since-last-visit diff and the daily checklist on Journal; the six overlooked exposures on Theses; the twelve monitoring signals on Decide; the transmission map on The brain; market moves and key levels on Rates; the growth-inflation quadrant and the correlation gauge on the Decision loop; the engine readout on the Engine room. Today keeps the call, what changed, what would reverse it, how far to trust it and the calendar." },
    { g: "v0.22", q: "Today looks like 1972 or 2000 on the geometry desk. Should the book act on that?", a: "No. Those are the past 36-month windows whose volatilities and correlations of stocks, Treasuries and gold sit nearest today's on the curved space of covariance matrices. Walked forward since 1940, averaging what followed the nearest windows forecast the next year's return worse than the plain historical mean (skill -15%), and matching whole distributions did worse still (-26%). The resemblance is real; its predictive value is not." },
    { g: "v0.22", q: "If analogs do not predict, why did the decision engine add an analog model?", a: "Because, scored on the whole next-month distribution rather than a point forecast, a mixture of eight past years beats one bell curve (t 4.0), and model averaging gives it about 12% of the weight. The placebo shows why: eight windows drawn at random do as well. A mixture of several pasts has fatter tails, which is what real months have. The engine keeps the model for that and shrinks each analog's mean three quarters of the way to the long-run average." },
    { g: "v0.22", q: "What do random matrix theory and topology add?", a: "A count and a picture. Of 27 world-market series over ten years, two eigenvalues rise above what pure noise would give, the dollar and then oil with rates, so most apparent structure in a correlation table is sampling noise. Persistent homology shows how markets join and where loops form. Neither the absorption ratio's jumps nor loop persistence warned of 10% falls reliably enough to survive the correction for testing many." },
    { g: "v0.21", q: "Does the matrix shortcut change any answer?", a: "No, where it is used. The scan and the batched fits give the same odds and the same fits as the month-by-month versions to about 1e-12, the batched neural ensemble the same weights bit for bit, and the batched spread the same activation for every question; the tests check each against the version it replaced. The one shortcut that does change answers, the 64-number map of the graph, is shown with its error and used only to suggest related ideas." },
    { g: "v0.21", q: "What is Pearl, and why is it on this site?", a: "A blockchain whose miners prove work by doing matrix multiplications, the math AI inference runs on, so the same computation can serve an AI customer and win a block. It sits here because it is a direct bet on the demand for matrix math that the book's chip holdings sell into, and because the engine was rebuilt on the same idea. The desk quotes Alea Research and Bankless for the facts and lists what would have to be true." },
    { g: "v0.20", q: "Why not hold 60/40, or what the learner holds?", a: "The engine's investor is calibrated so that holding stocks is optimal in an average month, and for that investor neither 60/40 nor the learner was better than holding: both lowered expected utility, though both cut the worst drawdown by a fifth or more at about the same Sharpe. The portfolio desk shows every policy's record so a reader with more risk aversion can see the trade: raise risk aversion on the decision desk and the answer moves." },
    { g: "v0.20", q: "Do Treasuries hedge stocks now?", a: "In the portfolio engine's regime model, the most likely state for next month has a stock-bond correlation of about +0.15: in that state Treasuries have not hedged stocks. Only a state with a negative correlation would make long bonds a hedge; the desk shows each state's correlation and its odds." },
    { g: "v0.19", q: "Why does the decision engine hold 1x when its own optimum says otherwise?", a: "Because its record says it should. Walked forward since 1940 with costs, the engine's departures from 1x did not make a risk-averse investor measurably better off than holding, so its evidence gate scales them to nothing. The optimum, its drivers and what would flip it are all shown; when the record improves, the gate opens on its own." },
    { g: "v0.19", q: "Is the neural network better than the simple models?", a: "No. A deep ensemble of small, heavily regularized networks forecasts 12-month returns worse than the historical mean out of sample, like every flexible model on the ML desk; the stacking weights, fit only on past forecasts, give it little weight. Its value is honest uncertainty: its bands widen when today's inputs are unlike the past." },
    { g: "v0.19", q: "Can the decision engine trade?", a: "No. It writes a decision for the MODEL book with its reasons and its record. The MCP tool decision_engine only reads; nothing in the engine places orders." },
    { g: "v0.18", q: "What happens if an engine fails in the daily run?", a: "It fails alone. Each engine runs in its own process with a time limit; a crash, a hang or a file that breaks its contract (missing fields, a number that is not finite, a yield outside 0 to 25%) is caught, the previous good files are put back, and the engines that read them run on those, marked as reading last-good inputs. The run manifest records it all." },
    { g: "v0.18", q: "How do I check the installation is healthy?", a: "Run python -m buildout doctor. It checks the Python environment, that no secret is in a tracked file, the mind graph, that every knowledge item is sourced and checked, that every concept's relations resolve, that each bond ladder reproduces its fund's reported duration, the engine graph, the page snapshots and the cache, and exits non-zero if anything fails." },
    { g: "v0.17", q: "If the 10-year and 30-year both go to 4%, what is TLT worth?", a: "About $99 from $80.24 at the Oct 21 close, a gain of about 23%, plus about 5% of income and roll over a year. At 6% for both, about $73 (a loss of about 9%). The Bonds desk reprices TLT and the other Treasury ETFs bond by bond at any pair of yields; the mind answers the same question when you type it." },
    { g: "v0.17", q: "Why does TLT gain more on a fall in yields than it loses on a rise?", a: "Convexity. A bond's price bends with its yield, so a one-point fall earns more than a one-point rise costs, and the longer the bond the more it bends. For TLT today the gap is about 3 points on a 1.4-point fall." },
    { g: "v0.17", q: "Why did the complex models backtest better but forecast worse?", a: "Because the history is shorter than it looks and the signal is weaker than the noise: about 142 independent 12-month observations, predictors that barely move, and a true R squared of a few percent. A flexible model spends that data memorizing the past, extrapolates into ranges it never saw and learns details that drift. The ML lab measures each of these." },
    { g: "v0.17", q: "What is the chronicle?", a: "Every month since 1871 as a node of the mind, with its valuation, rates, inflation, drawdown and what the next 12 months returned, linked to the eight months most like it, to its year and to named episodes. Ask the mind about March 2009, 1974, Black Monday or months like now." },
    { g: "v0.16", q: "How does the composite technical score work?", a: "Each signal is +1, -1 or 0 today. Its weight is t squared over t squared plus 4, where t is the Newey-West t-statistic of its edge on the asset's own history, and zero if the edge has the wrong sign. The composite is the weighted sum divided by the number of signals, so weak evidence pulls it toward zero. It is also judged out of sample: weights from the first half of history, scored on the second." },
    { g: "v0.16", q: "What changed in the machine-learning lab?", a: "A seventh model, the Rapach-Strauss-Zhou combination of eight one-variable forecasts with Campbell and Thompson's sign restrictions and a zero floor, is the first to beat the historical mean out of sample, by 2.5% skill (t 1.45, not yet significant). An accuracy-weighted ensemble was added beside the equal-weight one. Random forests now use both processor cores." },
    { g: "v0.16", q: "Where does the engine get prices for the holdings?", a: "The data hub tries Databento first (with your key, split-adjusted), then Yahoo's chart API, then Stooq, and records which one answered for each ticker. Filings come from the SEC's company facts with your contact string. The daily Action runs it; python -m buildout connect checks every source and key." },
    { g: "v0.16", q: "What made the engine faster?", a: "The mind's layout now computes forces without building large temporary arrays and places its galaxies with vectorized math (about three times faster), and the page no longer runs the full scenario solver at load; it runs when you open the Solve desk." },
    { g: "Start here: the engine in plain English", q: "What is the machine-learning lab, and does machine learning predict the market?", a: "A test of whether seven models, from a one-line CAPE regression to gradient boosting, could have forecast the next year of stock returns using only what was known at the time, every month since 1940. Only the simplest, a restricted average of one-variable forecasts, beat simply assuming the long-run average, and by a small margin. In cross-validation, the most complex model fitted the past best and forecast the future worst. That is the useful result: treat any return forecast that has not passed this kind of test as a story." },
    { g: "Start here: the engine in plain English", q: "What do 'purged' and 'walk-forward' mean?", a: "Walk-forward: the model is trained on the past, makes a forecast, then the clock moves on and it is retrained, so it never sees the future. Purged: because each outcome is a 12-month return, the 12 months just before a forecast are dropped from training; otherwise the model would be trained on part of the answer." },
    { g: "Start here: the engine in plain English", q: "What is the reality check?", a: "The answer to a PM's complaint: quants arrive with models whose assumptions break in the real world. The reality check lists every model the engine runs, what each assumes (normal returns, independent months, a stable world, bonds hedging stocks, a known edge), tests each assumption on the data, and says what the engine does when one breaks." },
    { g: "Start here: the engine in plain English", q: "What is a breakpoint?", a: "The value at which a conclusion flips. The TLT hedge lowers the book's risk only while the stock-bond correlation is below about -0.09; the trend rule's advantage disappears at about 56 basis points of cost a switch. Knowing the breakpoint turns 'the model is wrong' into 'the model is wrong by more than this', which you can check." },
    { g: "Start here: the engine in plain English", q: "How do I judge a quant's backtest?", a: "Use the triage on the Reality check desk: enter the Sharpe, the years, how many versions were tried and the trading costs. It takes off costs, then the decay that published strategies suffer live (26% lower out of sample, 58% after publication, McLean and Pontiff), then asks whether the result beats what luck alone would produce from that many tries. Then ask the seven questions under it." },
    { g: "Start here: the engine in plain English", q: "What is Taleb's kappa?", a: "A measure of how fat the tails are, scaled from 0 (a bell curve) to 1. It translates into data: monthly stocks have a kappa near 0.13, so it takes about 39 months to learn what 30 months would teach if returns were normal. Fat tails make every average less reliable than it looks." },
    { g: "Start here: the engine in plain English", q: "What is the information edge desk?", a: "A list of sources worth reading and what each is uniquely good for (BowTied Bull, SixSigmaResearch, SemiAnalysis, Stratechery, Doomberg, Taleb, Damodaran, Berkshire letters, Oaktree memos, SEC filings, the Fed's weekly balance sheet, futures positioning), with what to watch for in each. An information edge is rarely a secret; it is a primary source read sooner and more carefully." },
    { g: "Start here: the engine in plain English", q: "What is the implied equity risk premium?", a: "Damodaran's way of reading what the stock market expects to earn: find the discount rate that makes today's index equal to the cash it is expected to pay out, then subtract the risk-free rate. On October 1, 2026 his estimate was 4.20% over a 5.29% Treasury." },
    { g: "Start here: the engine in plain English", q: "What is a what-if question?", a: "Ask 'What if oil spikes, what happens to the book?' The mind sets the claim 'oil keeps rising' to 90% and lets every connected claim re-settle through the belief network, then shows how the model book's exposure changes. It is a consistent way to follow a shock, not a forecast that the shock will happen." },
    { g: "Start here: the engine in plain English", q: "Can I use Vim or Emacs keys?", a: "Yes. Press ? and pick Vim or Emacs, or press : and type set keys=vim. Vim: j and k scroll, gg and G jump, ]] moves by section, gt by desk. Emacs: C-n and C-p scroll, C-s searches, M-x opens the command line. The command line takes think, whatif, go, triage and erp. The repository also ships editors/buildout.vim and editors/buildout.el, which ask the same engine from inside either editor." },
    { g: "v0.15", q: "How are the ML forecasts scored?", a: "Out-of-sample R squared against the expanding historical mean (Campbell and Thompson), a Diebold-Mariano test with Newey-West errors at 12 lags, and for the crash model the Brier score and AUC. Refits every 12 months from 1940, with a 12-month purge and a one-month embargo." },
    { g: "v0.15", q: "What is the probability of backtest overfitting?", a: "From combinatorial purged cross-validation: eight blocks, train on six and test on two, all 28 ways. It is the share of splits in which the configuration that ranked first in training ranked below the median in testing: 82% here for the return models." },
    { g: "v0.15", q: "Why does the belief network cap the pull of connected claims?", a: "Because connected claims share evidence: if market valuation and Nvidia both lean bearish partly on the same reading, letting one push the other at full strength would count that reading twice. The network row is capped at 0.3 in log-odds, and links weaker than 15% of the strongest are dropped." },
    { g: "v0.15", q: "Where do the network's links come from?", a: "Each claim has a representative market series in the atlas (Brent for oil, CPI for inflation, the 10-year for bonds, Nvidia for semiconductors). The link from claim A to claim B is the 12-month cumulative response of B's series to a one-standard-deviation shock to A's in the atlas's structural model, sign-adjusted and scaled so the strongest is 1." },
    { g: "v0.15", q: "What are stressed worlds?", a: "Four hundred alternative 50-year histories built by resampling 12-month blocks of the real record of stocks, bonds and inflation, then again drawing only from inflationary months. The 60/40 mix beat all stocks on Sharpe in 88% of all worlds and 4% of the inflationary ones: the case for bonds is a case about the regime." },
    { g: "v0.15", q: "Do the editor plugins run anything the page does not?", a: "No. buildout.vim and buildout.el call python -m buildout think, triage, erp and dcf in your copy of the repository and show the text. They cannot place orders; nothing in the engine can." },
    { g: "v0.14", q: "How much bigger did the brain get in v0.14?", a: "About 1,524 nodes and 3,800 typed links in one graph, from 100 nodes in v0.13: 547 concepts in 18 galaxies, the atlas's 100 nodes (72 measured markets and 28 judged drivers and holdings), 268 checked facts and papers, 267 quotes from 60 investors on 18 topics, 62 engine modules with their imports as links, 10 lab methods, 19 MCP tools, 48 economies and 107 signals." },
    { g: "v0.14", q: "Is the mind's verdict a forecast?", a: "No. It is the balance of the evidence the engine holds, weighted by how reliable each kind has proved, with an honest range. It does not know prices tomorrow. The weights are set in the open (strength, reliability, family) and every signal says what reading would flip it." },
    { g: "v0.14", q: "Why do the mind's verdicts sit near 50%?", a: "Because most market debates are genuinely two-sided on the evidence: stocks are expensive and earnings are growing fast; oil is short now and forecast to fall. The verdicts move when the evidence is lopsided: active managers beating the index scores about 21% because only a quarter did over ten years and fees are a certain drag." },
    { g: "v0.14", q: "What changed in the trend-rule test, and why?", a: "Shiller's monthly prices are averages of daily closes, which makes returns look smoother and more persistent than they were (Working 1960). A rule that acts on the same month therefore looks better than it could have been (Sharpe 0.80). Acting a month late removes the artifact: Sharpe 0.64 against 0.56 for holding, with a gain whose range includes zero." },
    { g: "v0.14", q: "Why leave out the World Bank inflation numbers?", a: "The public mirror's consumer-price file matched the GDP deflator for the countries checked (for example, the US at 3.6% for 2023, where the consumer-price figure is about 4.1%), so it was dropped rather than mislabelled. GDP and population are used." },
    { g: "v0.13", q: "How big was the atlas in v0.13, and how much of it is measured?", a: "100 nodes in the atlas (the whole mind is now far larger): 72 monthly series (equities, rates, inflation, energy, metals, grains, oilseeds, softs, livestock, 19 currencies) and 28 judged concepts and holdings. Its measured part went from 6 series and 11 links to 72 series and 189 learned links (116 same-month, 21 from one series to another next month, 52 own-momentum), against 106 judged. The daily run adds about 30 FRED series (credit, the curve, jobs, activity, money, housing, bitcoin) and current commodity prices, so it grows to roughly 130 nodes." },
    { g: "v0.13", q: "Why trust learned links?", a: "Each one has passed four filters: the graphical lasso at the penalty the extended BIC picks, selection in at least 70% of 60 half-samples, a direction from its non-Gaussian signature, and |t| of at least 2 (Newey-West) once its child is regressed on all its parents. On a planted graph the pipeline recovers every causal link, at least 80% of what it keeps is real, and at least three quarters point the right way. The established links carry a bound of under six expected false. The Monte Carlo then drops each link with its own chance of being spurious." },
    { g: "v0.13", q: "Why are currencies the most systemic series?", a: "Because the dollar runs through all of them: a move in the euro or the Australian dollar comes with moves in most of the others the same month, so in the total-effect matrix they reach the most series. Read it as the dollar factor, which the free data do not give as its own series; in the daily run FRED's broad dollar index joins as a node." },
    { g: "v0.12", q: "Where do the investor quotes come from, and can they be made up?", a: "From a curated library: every quote was found on its source page, is verbatim (punctuation aside), dated, and linked. Retrieval only ranks the library. The optional Claude step can reorder quotes and summarize a side in its own words, labelled as Claude's; any quote id it returns that is not in the library is dropped, so it cannot add a quote." },
    { g: "v0.12", q: "How far can the brain be trusted?", a: "It now checks itself out of sample from 2000. Its 90% error bars on stocks covered 90% of months with adaptive conformal intervals and 88% with textbook ones. Since 2022 the stacked ensemble puts most weight on the model with no same-month link to stocks at all, and an unseen common cause would need to explain about a fifth of both variances to erase the 10-year-to-stocks link. Direction is better supported than size." },
    { g: "v0.11", q: "Is the market being irrational about the AI names?", a: "The engine reads each price as a requirement, not a forecast. On October 20 prices and the latest filings, Nvidia, Amazon, Broadcom and Tesla need revenue growth that fewer than 1 in 100 companies of their size have ever achieved for a decade; Microsoft, Alphabet, Meta and Oracle need growth fewer than 1 in 20 achieved (Meta and Oracle once cash flow lifted by prepayments and deferred taxes is taken out). That is not proof of irrationality: Nvidia and Broadcom are already growing far faster than their prices require. The Positions desk shows both sides, each in points of required growth." },
    { g: "v0.11", q: "Why would long Treasuries not protect a crash?", a: "In the solver's liquidity-crash scenario yields rise as everything is sold, and since 2022 the 10-year yield has risen, on average, in stocks' worst months. TLT protects a growth scare or a soft landing; puts, collars, VIX calls, index shorts and cutting equity protect the crash. The hedge book lets you switch each on and see the difference." },
    { g: "v0.11", q: "Does the decision loop trade?", a: "No. It writes proposals, each with a confidence, a kill criterion and a note that it is a two-way door, for a person to review. The MCP server's decision_loop tool returns the same record to any assistant, and Robinhood's own MCP is where an approved change would be placed." },
    { g: "v0.10", q: "How robust is the stock-bond flip the hedge rests on?", a: "Less than its average suggests. Since 2022 the 10-year-to-stocks link reads −0.24, but with Newey-West errors its t-statistic is −1.5, and dropping three months (September and October 2022, October 2023) reverses its sign. The pre-2022 positive link reverses on seven. The direction of the regime change is plausible; its size is not established. That is one more reason the hedge desk leans on the live correlation rule rather than on the link estimate." },
    { g: "v0.10", q: "What does robust to the odds mean on the Solve desk?", a: "The scenario probabilities are estimates. The robust solver asks which portfolio has the best worst case across every set of odds within a stated Kullback-Leibler distance of the estimate, and shows what that protection costs in nominal growth. If the choice changes at a tiny distance, the nominal answer was leaning on the exact odds." },
    { g: "v0.10", q: "Is the backtest overfit?", a: "Each run now measures it: 30 neighbouring hedge rules are backtested, the history is split 924 ways, and the probability of backtest overfitting is the share of splits in which the in-sample winner falls to the bottom half out of sample. Block-bootstrapped intervals show how wide each policy's Sharpe and drawdown could have been on another path." },
    { g: "v0.9", q: "Is the brain's map still right about bonds?", a: "The brain now checks itself. Bayesian model comparison says today's readings are more probable under the 1990 to 2021 links than the 2022-on ones, and the Kalman smoother shows the 10-year-to-stocks link went negative in mid-2021 and has drifted back near zero since early 2025, with a wide band. Neither is a verdict; both say the 2022 break may be fading, which is exactly what the hedge desk should watch." },
    { g: "v0.9", q: "Does Ask the brain make numbers up?", a: "It is told not to, and it cannot do the arithmetic itself: every figure comes from a function on the page (think, shock, counterfactual, loss story, channels, learned structure), each call is listed as it happens, and the functions are the same ones tested against Python. It uses your own Claude usage and asks permission first." },
    { g: "v0.9", q: "Did the data confirm the brain's causal order?", a: "Partly. On 1990 to 2021 monthly data, DirectLiNGAM orders 9 of 15 pairs the way the map assumes. Three orderings hold in at least 80% of resamples (oil before the 10-year, stocks before the 10-year, VIX before the 10-year); most others are close to a coin flip. The order stays an assumption, now with its evidence shown." },
    { g: "v0.8", q: "Does the brain actually think?", a: "It reasons in four exact steps. It explains (which root shocks fit every reading at once, and which single cause is most likely against \"nothing happened\"), deduces (what must then be true of each holding and the book, with uncertainty), doubts (which reading it cannot explain and which link is most to blame), and asks (which unobserved node would best separate the explanations it cannot tell apart). Every step is linear algebra on a published graph, checked against Python." },
    { g: "v0.8", q: "Why is an anecdote not a signal?", a: "Because it has no date, no denominator, no baseline and no competing explanation until someone writes them down. The Field desk forces those fields, compares the explanations by Bayes' rule, and registers each unusual indicator with its target and horizon before it is tested, so a lucky story cannot quietly become a rule." },
    { g: "v0.8", q: "Can the MCP server trade?", a: "No. It has 41 tools (nine at v0.8) and none places, routes or cancels an order. analyze_positions reads holdings you pass in for that one call and stores nothing. create_order_proposal returns a hashed proposal marked unexecuted for a person to review. The server refuses the private config with real positions; tests check both." },
    { g: "v0.7", q: "Is the solver a forecast?", a: "No. It turns stated assumptions (scenarios, their priors and the likelihood of each signal) into a choice that respects your loss limit, and shows which assumption moves that choice. The scenarios and likelihoods are labelled Assumed and Hypothesis; the signals are Observed; covariances are Estimated." },
    { g: "v0.7", q: "Why does the solver hold less equity than the engine's size?", a: "Different questions. The engine sizes the equity book to a volatility target and a drawdown cap. The solver asks what keeps the worst of seven 3-month scenarios inside a loss limit while growing fastest. With a 15% limit and a liquidity crash on the list, the full book fails; the solver cuts equity, adds put spreads and gold, and says which signal would change that." },
    { g: "v0.7", q: "What is game theory doing in a risk tool?", a: "Other players set the prices the book lives on. The builders' capex race explains why returns on capacity fall even when demand is strong; the crowded-exit game gives the threshold at which a crowded trade runs; Kyle's model prices what your own order reveals. Each is solved exactly and labelled with its assumptions." },
    { g: "The project", q: "What is this, in one sentence?", a: "A risk desk for a concentrated AI-buildout equity book: it measures when long Treasuries hedge that book, prices the alternatives, and sizes positions so a bad year is survivable." },
    { g: "The project", q: "Does it predict returns?", a: "No, on purpose. It forecasts risk (volatility, correlation, drawdown) because those forecasts are reliable. Its one return model runs walk-forward and is judged on calibration; in the planted test it finds an edge only where one exists." },
    { g: "Decisions", q: "Why does the desk say bonds will not hedge?", a: "Because stocks and bonds are moving together today: the stock-bond state is the gate that binds. The inflation finding is weaker than the headline once was: the line chosen on data through 2016 is 4.25%, a bootstrap puts it anywhere from 2.75% to 4.25%, and today's 3.06% sits inside that band. Out of sample since 1901, adding the inflation gate to the correlation rule did not improve the worst months." },
    { g: "Decisions", q: "Why did the inflation figures change in v0.5?", a: "The federal shutdown meant BLS published no CPI for October 2025. Code that drops the missing month and shifts by 12 rows silently measures 13 months of inflation: August 2026 read 3.69% instead of the 3.4% BLS published. The engine now builds a full monthly calendar and fills a one-month gap geometrically, and prefers BLS and the Treasury's 10-year over Shiller's preliminary last months. The September print (3.7% on Oct 14) is in." },
    { g: "Decisions", q: "How is a decision's confidence computed?", a: "As the product of the probabilities of the assumptions it rests on, each written down with its evidence and the test that would falsify it. Move an assumption's slider and every decision that uses it updates. A product assumes independence; assumptions that fail together make it a floor on the risk." },
    { g: "Decisions", q: "How does the journal tell luck from skill?", a: "Four ways: a Brier score and calibration chart for the stated odds; alpha after the market's share (return minus beta times the benchmark); a binomial test of the hit rate against a coin flip; and a two-by-two of process against outcome, so a good result from a bad process is labeled luck." },
    { g: "Decisions", q: "Where are my journal entries stored?", a: "In the published page, in your own private space on the artifact: no one else can read it, the owner included. Opened anywhere else, in this browser's storage. Export writes a JSON file that the engine scores with python -m buildout journal." },
    { g: "Decisions", q: "Why rates of change rather than levels?", a: "Markets price the change before it shows in the level. The Findings desk measures it: since 1880, the next year's real return averaged 11.6% when earnings growth was negative and slowing, against 6.2% when it was positive and speeding up. Every signal shows its velocity, acceleration and time to its rule's line." },
    { g: "Decisions", q: "Are the findings data-mined?", a: "The hedge line is now chosen only on data before an untouched final decade, walked forward in 20-year blocks, and bootstrapped in 36-month blocks that re-choose the cut each time; the engine can return no reliable threshold, and the policy then drops the inflation gate. The deflated Sharpe counts every variant, hedge policy and candidate hedge tried, not only the four on display. Small samples (9 oil shocks, 16 VIX spikes) remain direction, not law." },
    { g: "The project", q: "Is this investment advice?", a: "No. It is a research tool. The book is a model book, the theses are research positions with written kill criteria, and every tool input is an assumption to stress." },
    { g: "The project", q: "Who is it for?", a: "Anyone running concentrated equity risk who has leaned on bonds as the hedge: a portfolio manager, an allocator, or an individual with a large technology position." },
    { g: "Data", q: "Where does the data come from, and what does it cost?", a: "FRED, free, for rates, credit, volatility, oil and the Nasdaq-100 back to 1986. Databento, pay as you go, for daily bars, corporate actions and CME futures. SEC EDGAR, free, for capex and cash flow. Kalshi, free, for event odds. Only derived analytics are stored; raw market data never enters git." },
    { g: "Data", q: "How fresh is it?", a: "The daily run fires before the US open, Tuesday to Saturday, so it reads the prior close. Every live number carries its date, and the page flags anything more than three weekdays old." },
    { g: "Data", q: "What happens when a source fails?", a: "Each FRED series downloads on its own; a failure is recorded and the run continues without it. A status file lists every check and the Engine desk shows it. An invalid file shows an error on its own panel without breaking the rest of the page." },
    { g: "Data", q: "Why FRED's 20-year yield instead of TLT prices?", a: "History. TLT starts in 2002; the 20-year yield runs back to 1993 and lets the engine test the hedge through the 1994 rout, 2000, 2008, 2020 and 2022. The book run uses TLT itself once Databento data is in." },
    { g: "Method", q: "Why a 63-day half-life for the correlation?", a: "About one quarter: fast enough to catch a regime turn within weeks, slow enough not to chase noise. The one-year rolling correlation sits beside it as the slow read." },
    { g: "Method", q: "Why the ±0.10 band and hysteresis?", a: "A hedge that flips on and off around zero pays costs and is right half the time. The engine turns the bond hedge on only once correlation is clearly negative, and off once it turns positive." },
    { g: "Method", q: "Why long-only hedge ratios?", a: "The question is whether to hold bonds as insurance, not whether to short them against stocks. That is a different trade with its own risk." },
    { g: "Method", q: "Why minimum-variance and not a fixed 30%?", a: "The fixed hedge is the benchmark to beat. In the inflation regime it kept buying bonds while they fell with stocks. In the synthetic test the regime-gated ratio cut variance 5.0% while the fixed hedge added 0.6%." },
    { g: "Method", q: "Why Black-Scholes when the market has skew?", a: "It is the common language for Greeks and a clean baseline. The tail-budget tool lets you raise implied volatility at the strike to reflect skew, the implied-volatility solver reads it back from a market price, and the roadmap replaces assumed volatility with listed option chains." },
    { g: "Method", q: "Why size with risk limits and use Kelly only as a check?", a: "Kelly needs the expected return, the input known least: halve the edge and the Kelly bet halves. Volatility targets and drawdown caps need only volatility, which forecasts well. Kelly then asks whether the return you believe in justifies the size the limits allow." },
    { g: "Method", q: "How realistic is the drawdown simulation?", a: "It is a floor. It assumes normal daily returns and daily rebalancing; real markets gap and have fat tails, so real drawdowns at the same leverage are worse. That is why the cap uses the 95th percentile and the gross limit stays at 1.5x." },
    { g: "Method", q: "What is the deflated Sharpe ratio, and why use it?", a: "The probability that a backtest's Sharpe is real after charging for how many variants were tried and for skew and fat tails. Every variant, hedge policy and candidate hedge tried is counted, not only the four on display, so the best one has to clear a higher bar than its raw Sharpe suggests." },
    { g: "Results", q: "What is the backtest Sharpe?", a: "The live book panel reports it beside the deflated Sharpe once the Databento key is in. The synthetic tests prove the machinery recovers planted answers; by design they say nothing about markets." },
    { g: "Results", q: "How do you know the backtest is not cheating?", a: "A canary. A signal known at today's close earns nothing on a random walk (Sharpe 0.28), while a signal that peeks one day ahead posts a Sharpe of 21. If timing ever leaked, the canary would fail the build." },
    { g: "Results", q: "What has the data said about bonds as a hedge since 2022?", a: "That they stopped being reliable. The Fed's own measure was +0.21 on Jul 31, 2026. Bonds still rallied in growth scares, as on Oct 8, 2026, but fell with stocks in inflation and supply shocks: March 2026 and the week of Apr 7, 2025." },
    { g: "Markets", q: "Why do stocks and bonds sometimes fall together?", a: "When inflation or bond supply drives rates, higher yields hit both: bonds directly and stocks through higher discount rates. When growth drives markets, falling yields cushion stocks. The sign of the correlation tracks which shock dominates." },
    { g: "Markets", q: "If not bonds, what hedges the book?", a: "Contracts, not correlations: index put spreads for fast drawdowns, credit protection for an AI financing break, energy for an oil shock, and lower gross through volatility targeting. The hedge matrix grades fifteen candidates across six scenarios." },
    { g: "Markets", q: "What does tail protection cost?", a: "Rolling 85%-strike puts on the whole book at 30% implied volatility costs about 3.4% of NAV a year in the tail-budget tool, and a −35% quarter then pays about 20%. Put spreads cut the cost by giving up the deepest tail." },
    { g: "Markets", q: "Why does an insurer's balance sheet matter to an equity book?", a: "Insurers are the marginal buyers of the long-dated debt that funds data centers; Meta's Hyperion bonds went to PIMCO, which Allianz owns. If their appetite slows, AI financing costs rise: the lane where bonds fail as a hedge." },
    { g: "Markets", q: "What is the curve paying for duration right now?", a: "On the Oct 21 curve, a financed 2-year earns about 0.84% a year from carry and roll-down and can absorb an 87bp rise; a 30-year earns about 1.0% and absorbs only 7bp, because the 20-year kink makes it roll up the curve, not down. Per unit of risk, the front end is where carry is." },
    { g: "Markets", q: "What is the single most important insight here?", a: "A bond hedge is a bet on which kind of selloff comes next. Measure the regime every day, and buy protection that pays regardless of the cause." },
    { g: "Market reads", q: "What is the desk read, and how is it computed?", a: "A one-line summary above the signals board. Each signal maps its amber or red state to the playbook it argues for; the read adds the votes, red counting twice, and names the closest playbook once it has three or more. It is a tally, not a model." },
    { g: "Market reads", q: "Why can bonds hedge in a week while the regime says they amplify?", a: "The regime is a 63-day average and a week can go the other way. From Oct 13 to Oct 16, the 30-year yield fell 13bp while the Nasdaq-100 dropped on AI credit worries: a growth-and-credit scare inside an inflation regime. The rule holds no bond hedge until the correlation crosses −0.10, so one good week does not flip it." },
    { g: "Market reads", q: "How do I know whether puts are cheap right now?", a: "Compare implied volatility with its own history and with realized. The Options desk ranks VXN against ten years and against the Nasdaq-100's realized volatility; cheap is the bottom third with a small premium. The VIX curve adds timing: when it inverts, stress is already priced." },
    { g: "Market reads", q: "What does an inverted VIX curve mean for a hedger?", a: "The market prices the next month as more dangerous than the next three. It shows up in sharp selloffs and is usually the worst moment to buy protection and a good one to start monetizing it. The engine counts the inverted days in the past year." },
    { g: "Market reads", q: "What is net liquidity, and does it drive stocks?", a: "Fed assets minus the Treasury's cash account minus reverse repo: the cash the Fed leaves in the private system. It is an accounting identity, not a law of prices. The desk uses it to see who is draining cash and how close reserves are to scarce, not to time the index." },
    { g: "Market reads", q: "Why watch SOFR against IORB?", a: "Banks can earn IORB at the Fed without risk, so repo should trade a little below it while reserves are ample. Repo above IORB means cash is scarce. In September 2019 repo rates spiked and the Fed had to add cash; in October 2025 it cited money-market conditions when it decided to stop shrinking its balance sheet." },
    { g: "Market reads", q: "Why does the CCC spread matter when high yield looks calm?", a: "The weakest borrowers feel tight money first. On Oct 16 the broad high-yield spread was about 3.3%, tight by history, while CCC and lower paid 12.97%, up from 8.53% in July 2025: stress concentrated at the bottom of the ratings, where thesis 6 expects private-credit losses to surface." },
    { g: "Market reads", q: "Why is the yen in the table?", a: "The yen funds global carry trades. A sharp yen rally forces them to unwind, as in August 2024, when the Nikkei fell 12.4% in a day. The table flags an unusual weekly yen move before it reaches volatility." },
    { g: "Market reads", q: "Is a 2σ week rare?", a: "Under a normal distribution about one week in 22 is a 2σ move. Market changes have fat tails, so they come more often: treat 2σ as worth a look and 3σ as news." },
    { g: "Data", q: "Why do the credit spread charts start in 2023?", a: "Since April 2026 FRED carries only the last three years of the ICE BofA spread indices; older history is licensed from ICE. The engine reads what FRED has, so the episode atlas shows credit moves only for recent episodes." },
    { g: "Implementation", q: "How would you put the hedge on?", a: "TLT for simplicity, or ZB and UB futures matched in DV01 to keep cash free; index put spreads on QQQ or NDX for convexity; HYG puts or CDX HY for credit. The futures calculator sizes the contracts." },
    { g: "Implementation", q: "How often would you rebalance?", a: "Daily signals, banded trades. The hedge ratio and gross update every day, but positions trade only when they leave a band (the 20% trim rule), which keeps costs and noise down." },
    { g: "Implementation", q: "What would you add with more resources?", a: "Listed option chains for real skew, intraday data for execution and liquidity, positioning data (CFTC, dealer gamma), and a paper-trading log that scores the desk against its own forecasts." },
    { g: "Engineering", q: "What is the stack?", a: "Python (numpy, pandas, scipy) for the engine, one self-contained HTML page with no framework, GitHub Actions for the daily run, and JSON files as the contract between them." },
    { g: "Engineering", q: "How is the page tested?", a: "Its bond, curve and option math runs in Node against the Python engine on every push, agreeing to about 1e−9, and property tests throw thousands of random bonds, curves and options at the engine (they found two real bugs). A browser suite feeds the page hostile and truncated files, hundreds of random inputs, clicks and resizes, every width from 320 to 1920 pixels, a full print and an accessibility audit; any script error, broken number on screen, sideways scroll or serious accessibility issue fails it." },
    { g: "Engineering", q: "How do I add a ticker or a thesis?", a: "Tickers and weights live in config.toml (priors for short histories too); theses live in site/src/data.js. Run the tests, run scripts/assemble_page.py, push." },
    { g: "v0.6", q: "What does the brain actually compute?", a: "It treats the system as a signed network: a shock at one node travels link by link, and the desk adds up what arrives at each order. Eleven links are measured from monthly data in two regimes; the rest are judged and editable. On top it finds the strongest channels, the feedback loops, the single link the answer depends on most, the share of 400 random worlds where the answer keeps its sign, and the cheapest combination of driver shocks that produces a given outcome." },
    { g: "v0.6", q: "What is the most important thing the brain measured?", a: "The sign of the link from the 10-year yield to stocks. From 1990 to 2021 a 1σ rise in yields came with stocks up 0.11σ the same month: rising yields meant good growth news. Since 2022 the same move comes with stocks down 0.24σ. That flip is why a long-bond hedge fails today." },
    { g: "v0.6", q: "How does the Noteworthy scraper find asymmetric information?", a: "It reads niche Substacks, a Telegram wire, X accounts (with an API token), Reddit, Hacker News and official feeds every morning, tags each item with themes, and scores each theme: heat against its own history, how much of the talk comes from niche sources, and, once three weeks of history exist, how many days the niche sources lead the mainstream." },
    { g: "v0.6", q: "Why not scrape X directly?", a: "X's terms forbid it. The engine uses the official API when an X_BEARER_TOKEN secret is set and skips X cleanly otherwise. Telegram public channels publish a web preview at t.me/s/<channel>, which is fine to read." },
    { g: "v0.6", q: "Where did the field manual and the data disagree?", a: "Brent (the manual quoted early-September futures; physical crude traded about $27 higher by mid-October), the real yield (1.6% is backward-looking: 10-year minus CPI; TIPS paid 2.74%), and the stock-bond correlation (+0.40 versus the engine's +0.15 and the Fed's +0.21, all positive). The rest agree." },
    { g: "v0.6", q: "Why does the challenge simulator's pass rate jump around?", a: "Because the rules are discrete. Above a certain risk per trade, one day of losses breaches the daily limit, and the number of winning trades needed to reach the target falls one whole trade at a time. The risk that maximizes the pass rate sits just below such a step." },
    { g: "v0.6", q: "Is market making just collecting the spread?", a: "No. The spread pays for adverse selection and inventory risk. The simulator shows that skewing quotes for inventory gives up a little average profit for much less risk, and the adverse-selection tool shows why uninformed retail flow is worth paying for." },
  ];

  METHODS.push({ group: "The atlas (v0.13)", items: [
    { name: "Skeleton", f: "Θ̂ = argmax log det Θ − tr(SΘ) − λ‖Θ‖<sub>1,off</sub>; EBIC = −2ℓ + E log n + 4Eγ log p, γ = 0.5", say: "S is the pairwise-complete correlation matrix (series have different spans), projected to the nearest positive definite matrix and shrunk 5% to the identity.", where: "atlas.py · Atlas" },
    { name: "Stability selection", f: "Π̂<sub>ij</sub> = share of 60 half-samples selecting i–j; E[V] ≤ q²/((2π − 1)P)", say: "Kept at Π̂ ≥ 0.7; established at Π̂ ≥ 0.9 under the loosest penalty whose bound is at most 10% of what it keeps.", where: "atlas.py · Atlas" },
    { name: "Direction", f: "R<sub>i→j</sub> = H(x<sub>j</sub>) + H(r<sub>i|j</sub>) − H(x<sub>i</sub>) − H(r<sub>j|i</sub>)", say: "Hyvärinen and Smith's pairwise likelihood ratio with maximum-entropy approximations; one global order chosen greedily from net evidence, so the same-month graph is acyclic.", where: "atlas.py · Atlas" },
    { name: "Structural VAR", f: "y<sub>t</sub> = B y<sub>t</sub> + A y<sub>t−1</sub> + e<sub>t</sub>; Φ<sub>0</sub> = (I − B)<sup>−1</sup>, Φ<sub>h</sub> = (Φ<sub>0</sub>A)<sup>h</sup>Φ<sub>0</sub>", say: "Parents pruned by backward elimination at |t| < 2 (Newey-West); lagged links kept at |t| ≥ 2.5; the companion matrix is shrunk if explosive.", where: "atlas.py · Atlas" },
    { name: "Connectedness", f: "θ<sub>ij</sub> = Σ<sub>h</sub>(Φ<sub>h</sub>)<sub>ij</sub>²σ<sub>j</sub>² / Σ<sub>h</sub>Σ<sub>k</sub>(Φ<sub>h</sub>)<sub>ik</sub>²σ<sub>k</sub>², total = 100 Σ<sub>i≠j</sub>θ<sub>ij</sub>/p", say: "Structural shocks are orthogonal, so the decomposition is exact. The index through time uses a ridge VAR per five-year window and the generalized decomposition.", where: "atlas.py · Atlas" },
    { name: "Communities and layout", f: "Q = (1/2m) Σ<sub>ij</sub>(A<sub>ij</sub> − k<sub>i</sub>k<sub>j</sub>/2m)δ(c<sub>i</sub>, c<sub>j</sub>)", say: "Newman's leading eigenvector, split while Q rises; each community laid out on its own and the discs placed by a force layout of the communities.", where: "atlas.py · Atlas" },
  ] });

  METHODS.push({ group: "The brain checks itself (v0.12)", items: [
    { name: "Order-by-order propagation", f: "x<sub>k</sub> = W′x<sub>k−1</sub>, S<sub>K</sub> = Σ<sub>k≤K</sub> x<sub>k</sub> → ((I − W′)<sup>−1</sup> − I)x<sub>0</sub> when ρ(W) &lt; 1", say: "The landing brain animates each order; the error after K orders shrinks like ρ<sup>K</sup>. 300 Monte Carlo worlds draw every link from its uncertainty.", where: "hero.js · Desk" },
    { name: "Stacking", f: "max<sub>w∈Δ</sub> Σ<sub>t</sub> log Σ<sub>m</sub> w<sub>m</sub> p<sub>m</sub>(y<sub>t</sub> | past)", say: "Five rival models per equation (full history, last 36 months, Huber, drifting links, no link), one-step-ahead from 2000; EM on the simplex.", where: "brain_robust.py · The brain" },
    { name: "Adaptive conformal inference", f: "q<sub>t</sub> = Quantile<sub>1−α<sub>t</sub></sub>(past |y − μ|/σ), α<sub>t+1</sub> = α<sub>t</sub> + γ(α − miss<sub>t</sub>), γ = 0.005", say: "Gibbs and Candès (2021): long-run miss rate equals α whatever the data do.", where: "brain_robust.py · The brain" },
    { name: "Robustness value", f: "RV = ½(√(f⁴ + 4f²) − f²), f = |t|/√df; at α: f − t*<sub>α,df−1</sub>/√(df − 1)", say: "Cinelli and Hazlett (2020); benchmarked against the strongest observed parent's partial R².", where: "brain_robust.py · The brain" },
    { name: "Voices retrieval", f: "relevance = 0.65 × topic BM25 (normalized) + 0.35 × quote BM25 (normalized); k<sub>1</sub> = 1.2, b = 0.75", say: "Phrases mapped to concepts, light stemming, synonyms; the same code in Python and the page, held equal by tests. Polarity reads bull and bear words with negation.", where: "voices.py · Desk" },
  ] });

  METHODS.push({ group: "Decisions, valuation and hedges (v0.11)", items: [
    { name: "Implied growth", f: "EV = Σ<sub>t≤10</sub> R<sub>0</sub>(1+g)<sup>t</sup>m<sub>t</sub>/(1+r)<sup>t</sup> + TV, m<sub>t</sub> = m<sub>0</sub> + (m* − m<sub>0</sub>)t/10, r = y<sub>10</sub> + βERP blended with debt", say: "Solved for g by bisection; m<sub>0</sub> is free cash flow after stock pay, m* the steady-state margin: the lower of after-tax operating earnings and OCF − D&amp;A − SBC, so working-capital inflows do not flatter it. ERP 4.5%, terminal growth 3%, inflation 2.5% (Assumed).", where: "valuation.py · Positions" },
    { name: "Base rates", f: "P(10-year real sales CAGR ≥ g − 2.5%) from the Base Rate Book's exhibit by starting size, uniform within bins", say: "Over $50B: mean 0.8%, sd 5.8%, 0.9% of companies above 15%. Empty bins carry a 0.05% floor.", where: "valuation.py · Positions" },
    { name: "Accounting quality", f: "cash conversion = OCF/core earnings; accruals = (NI − OCF)/assets; depreciation drag = 1 − (EBIT + D&amp;A − capex)/EBIT", say: "Core earnings replace net income when non-operating gains exceed 30% of it; flags graded watch or red.", where: "valuation.py · Positions" },
    { name: "Hedge book", f: "R<sub>s</sub> = book<sub>s</sub> + Σ<sub>on</sub> hedge<sub>h,s</sub>(size); options at VIX + skew, VIX calls lognormal at 100% vol", say: "Nine hedges, every on/off subset enumerated (512) for the cheapest set inside the loss limit, the best growth and the best worst case; 5bp a quarter running cost per hedge.", where: "hedgebook.py · Decision loop" },
    { name: "Granger, partial correlation, crisis behaviour", f: "F-test of two lags; ρ<sub>ij·rest</sub> = −P<sub>ij</sub>/√(P<sub>ii</sub>P<sub>jj</sub>), P = C<sup>−1</sup>; mean z in stocks' worst 10% of months", say: "On the six monthly series by regime; tail dependence at the 10% quantile; lead-lag to three months.", where: "causal_stats.py · The brain" },
    { name: "Position rules", f: "extreme: trim ½ (¼ if growing faster than required and accounting not weak); exuberant: hold and hedge (trim ¼ if weak and slower); pessimistic: add up to ¼", say: "Outside view sets the direction, inside view the size; each with a kill criterion. Stated in code, not forecasts.", where: "ooda.py · Decision loop" },
  ] });

  METHODS.push({ group: "Robustness (v0.10)", items: [
    { name: "Robust links", f: "Huber IRLS (c = 1.345, MAD scale); Newey-West with lags ⌊4(n/100)<sup>2/9</sup>⌋; Δβ<sub>(−i)</sub> = −(X′X)<sup>−1</sup>x<sub>i</sub>e<sub>i</sub>/(1 − h<sub>ii</sub>)", say: "Months ranked by influence toward zero, dropped one at a time and refitted until the sign reverses (at most 10% of the sample).", where: "robust.py · The brain" },
    { name: "Robust to the odds", f: "max<sub>x</sub> sup<sub>λ&gt;0</sub>[−λρ − λ ln E<sub>P</sub>e<sup>−u<sub>x</sub>/λ</sup>]", say: "The dual of the worst case over a KL ball, by golden section on ln λ; ρ = 0 is the ordinary solver, large ρ the maximin.", where: "reasoner.py · Solve" },
    { name: "Stationary bootstrap", f: "blocks of geometric length, mean 21 days, same draws for every policy", say: "Politis and Romano; 500 resampled histories give 5th to 95th percentile Sharpe, CAGR and drawdown, and paired win rates.", where: "analytics/robust_bt.py · Engine" },
    { name: "CSCV overfitting", f: "PBO = P[logit(rank<sub>OOS</sub> of the IS winner) ≤ 0] over C(12, 6) = 924 splits", say: "Bailey, Borwein, López de Prado and Zhu, on 30 neighbouring hedge rules.", where: "analytics/robust_bt.py · Engine" },
    { name: "Price screen", f: "|r<sub>t</sub>| &gt; 8 × 1.4826 MAD and reversed next day; 5+ unchanged closes while the market moved; gaps", say: "Flags, never edits; reported in the run status.", where: "data/quality.py · Status" },
  ] });

  METHODS.push({ group: "The brain checks itself (v0.9)", items: [
    { name: "Which world", f: "p(b | y) ∝ N(y; 0, 0.5<sup>2</sup>I + A<sub>b</sub>A<sub>b</sub>′), b ∈ {0, ¼, ½, ¾, 1}", say: "The readings' density under the map with links blended from the 1990 to 2021 regime (0) to 2022 on (1); Woodbury keeps it to a 10 by 10 inverse.", where: "thinking.py · The brain" },
    { name: "Surprise and leave-one-out", f: "d<sup>2</sup> = y′S<sup>−1</sup>y ~ χ<sup>2</sup><sub>n</sub>; z<sub>i</sub> = (S<sup>−1</sup>y)<sub>i</sub>/√(S<sup>−1</sup>)<sub>ii</sub>", say: "Exact conditional z-scores with no refitting; the page's incomplete-gamma tail agrees with SciPy.", where: "thinking.py · The brain" },
    { name: "Counterfactual and but-for", f: "x<sub>cf</sub> = x<sub>f</sub> + T<sub>cut</sub>[:, j](v − x<sub>f,j</sub>); share<sub>r</sub> = T<sub>book,r</sub>s<sub>r</sub>", say: "Abduction, action, prediction; in a linear map the but-for shares are Shapley values that add to the whole.", where: "thinking.py · The brain" },
    { name: "Channels", f: "Σ<sub>walks r→book, ≤K links</sub> s<sub>r</sub>Πw = T<sub>book,r</sub>s<sub>r</sub>", say: "Every walk enumerated with reachability pruning; the identity is tested to 1e-12.", where: "thinking.py · The brain" },
    { name: "How a bad quarter happens", f: "s* = s̄ + Ca(L − a′s̄)/(a′Ca), L = a′s̄ + √(a′Ca) Φ<sup>−1</sup>(p)", say: "The most probable root-shock combination reaching the loss; the runner-up holds the main driver still.", where: "thinking.py · The brain" },
    { name: "DirectLiNGAM", f: "pick argmin<sub>i</sub> Σ<sub>j</sub> min(0, Ĥ(x<sub>j</sub>) + Ĥ(r<sub>i|j</sub>) − Ĥ(x<sub>i</sub>) − Ĥ(r<sub>j|i</sub>))<sup>2</sup>, residualize, repeat", say: "Hyvärinen's maximum-entropy approximation for Ĥ; 200 seeded resamples for stability, shared between Python and the page.", where: "discovery.py · The brain" },
    { name: "Time-varying links", f: "y<sub>t</sub> = x<sub>t</sub>′β<sub>t</sub> + ε, β<sub>t</sub> = β<sub>t−1</sub> + η, η ~ N(0, qI); q by maximum likelihood", say: "Kalman filter and Rauch-Tung-Striebel smoother on standardized monthly changes since 1990.", where: "discovery.py · The brain" },
  ] });

  METHODS.push({ group: "The brain thinks, and the Field desk (v0.8)", items: [
    { name: "Abduction", f: "ŝ = (A′A + λI)<sup>−1</sup>A′y, A = T[observed, roots], λ = σ<sub>obs</sub>²/σ<sub>prior</sub>², Cov = σ<sub>obs</sub>²(A′A + λI)<sup>−1</sup>", say: "T = Σ<sub>k≤K</sub>(W′)<sup>k</sup>. The root shocks that best explain every reading at once, with their uncertainty and the share of the readings they explain.", where: "thinking.py · The brain" },
    { name: "Competing single causes", f: "y | cause j ~ N(0, σ<sub>obs</sub>²I + σ<sub>prior</sub>²a<sub>j</sub>a<sub>j</sub>′); ln p by Sherman-Morrison and the determinant lemma", say: "Each root alone, plus noise only, ranked by exact evidence with equal priors. Two causes with near-equal evidence are flagged as indistinguishable.", where: "thinking.py · The brain" },
    { name: "What to look at next", f: "I(H; X<sub>u</sub>) = h(Σ<sub>j</sub> p<sub>j</sub>N(μ<sub>uj</sub>, s<sub>uj</sub>²)) − Σ<sub>j</sub> p<sub>j</sub> ½ln(2πe s<sub>uj</sub>²)", say: "Mixture entropy by 801-point quadrature; the unobserved node whose value best separates the explanations.", where: "thinking.py · The brain" },
    { name: "Criticism", f: "r = (y − Aŝ)/σ<sub>obs</sub>; ∂‖r‖²/∂w<sub>e</sub> by finite difference", say: "The reading the map cannot explain, and the link whose change would cut the misfit fastest.", where: "thinking.py · The brain" },
    { name: "Doing vs seeing", f: "do(x<sub>i</sub> = v): T<sub>cut</sub>[:, i]·v with i's incoming links removed; seeing: re-abduce with y<sub>i</sub> = v", say: "Setting a value moves only its descendants; observing it also updates its causes.", where: "thinking.py · The brain" },
    { name: "Corporate actions without the paid feed", f: "P<sub>t</sub><sup>adj</sup> = P<sub>t</sub> · Π<sub>ex-dates &gt; t</sub> 1/ratio; bond funds: r<sub>t</sub> + (y<sub>t</sub> − fee)/252", say: "When Databento's adjustment factors are not on the plan, splits come from a public table and TLT and IEF earn the matching Treasury yield less fees each day (Estimated: it overstates income by the pull to par when the bonds trade below par). Stock dividends are left out. A one-day move above 45% still stops the run.", where: "data/corporate_actions.py · Engine" },
    { name: "Comparing explanations", f: "P(h | e) ∝ P(h)Π P(e<sub>k</sub> | h); value of checking e = H(h) − E<sub>e</sub>[H(h | e)] in bits", say: "Judged likelihoods per explanation; the unchecked evidence ranked by expected information.", where: "field.py · Field" },
  ] });

  METHODS.push({ group: "The solver, game theory and the policy contract (v0.7)", items: [
    { name: "Tempered Bayes", f: "π<sub>s</sub> ∝ prior<sub>s</sub> · Π<sub>drivers d</sub> exp(mean<sub>i∈d</sub> ln L<sub>i</sub>(o<sub>i</sub> | s))", say: "Seven signals, seven 3-month scenarios. Signals that share a driver are averaged, not multiplied, so one cause is counted once. Likelihoods are hypotheses, published on the page.", where: "reasoner.py · Solve" },
    { name: "Constrained growth search", f: "max Σπ<sub>s</sub> ln(1 + R<sub>s</sub>) s.t. min R<sub>s</sub> ≥ −L, e(1 + h) + g ≤ 2, premium ≤ budget", say: "Exhaustive over 18,414 portfolios (equity, TLT ratio, put-spread premium, gold); exact on the grid. Keep, reduce, hedge and optimal are compared on the same scenarios with regret.", where: "reasoner.py · Solve" },
    { name: "Game against Nature", f: "max<sub>x</sub> min<sub>s</sub> Σ x<sub>i</sub>R<sub>i,s</sub> by linear programming", say: "Simplex with Bland's rule; Nature's equilibrium scenario mix is the dual.", where: "reasoner.py · Solve" },
    { name: "Value of information", f: "EVSI<sub>j</sub> = Σ<sub>o</sub> P(o) max<sub>a</sub> E[U | o] − max<sub>a</sub> E[U]", say: "Each signal removed from the evidence and re-observed on and off; also whether flipping it changes the choice.", where: "reasoner.py · Solve" },
    { name: "Reverse stress", f: "s* = −L Σb/(b′Σb), d = L/√(b′Σb)", say: "Covariances of S&P 500, 10-year yield, Brent and gold changes, measured by regime and scaled to three months; the AI factor's 25% volatility is assumed.", where: "reasoner.py · Solve" },
    { name: "Nash equilibria", f: "pure: mutual best responses; mixed: A<sub>I,J</sub>y = v1, x′B<sub>I,J</sub> = u1′ on equal supports", say: "Support enumeration, exact for nondegenerate games; dominance, Pareto cells and the price of anarchy alongside.", where: "games.py · Games" },
    { name: "Asymmetric Cournot", f: "q<sub>i</sub> = (a − (N+1)c<sub>i</sub> + Σc<sub>j</sub>)/(b(N+1)); P = (a + Σc)/(N+1)", say: "a and b calibrated so the equilibrium reproduces observed capex at an assumed return on capacity; c<sub>i</sub> = 1/server life + cost of capital.", where: "games.py · Games" },
    { name: "Global game", f: "E[θ | x*] − λΦ(√β(x* − μ*)/√(1 + β/(α+β))) = −c", say: "Bisection; uniqueness checked by the monotonicity of the indifference curve. λ from square-root impact of the crowd.", where: "games.py · Games" },
    { name: "Hedge line, out of sample", f: "cut chosen on data before the last 120 windows; walk-forward by 20-year blocks; circular block bootstrap (blocks of 36 months)", say: "Status ok, no_reliable_threshold or insufficient_evidence; only ok carries a line into the policy.", where: "research.py · Findings" },
    { name: "One NAV convention", f: "r<sub>t</sub> = NAV<sub>t</sub>/NAV<sub>t−1</sub> − 1, NAV<sub>−1</sub> = 1, costs and financing inside NAV", say: "Inception cost in the first return; Sharpe in excess of accrued cash; next-session execution; every variant on the same dates; a cash-only baseline.", where: "analytics/backtest.py · Engine" },
  ] });

